INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('All-Star Summer Program', 'Boston Centers for Youth & Families (BCYF Charlestown Community Center)', 'https://www.boston.gov/departments/boston-centers-youth-families/bcyf-charlestown', NULL, 'CharlestownCC@boston.gov', '617-635-5170', '255 Medford Street', 'Boston', 'MA', '02129', 'Boston, MA', 'day', ARRAY['sports']::text[], ARRAY['swimming','general']::text[], ARRAY['sports','field games','gym games','pool time','team challenges','water games']::text[], 'coed', 7, 12, NULL, NULL, 'Free six week city summer program at the BCYF Charlestown Community Center for ages 7 to 12, weekdays 9 to 2, with sports, field and gym games, team challenges and pool time. An extended day to 4pm has limited spots.', 'both', NULL, 0, 0, 0, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '3f191d47-fcf5-566f-a013-da97e493e373', 'bcyf-charlestown-all-star-summer-program-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.boston.gov/departments/boston-centers-youth-families/bcyf-charlestown','https://www.boston.gov/sites/default/files/file/2026/05/BCYFSummerGuide2026_FinalV2.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Clark', 'Old Colony YMCA', 'https://www.oldcolonyymca.org/child-care-camps/camps/camp-clark', 'https://oldcolonyymca.my.site.com/s/registration?program=Camp%20Clark', NULL, '508-888-2290', '200 Hedges Pond Rd', 'Plymouth', 'MA', '02360', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','outdoor','nature','sports']::text[], ARRAY['swimming','boating','water obstacle course','archery','arts and crafts','basketball','soccer','t-ball','four square','hiking','fort building','survival skills','environmental awareness','fishing','ropes course']::text[], NULL, NULL, NULL, NULL, NULL, 'YMCA day camp on Hyles Pond in Plymouth, run in weekly themed sessions. Campers swim twice a day, go boating, try archery, crafts, sports and a ropes course, and explore the woods and pond.', 'outdoor', NULL, 415, NULL, 415, 'week', NULL, TRUE, TRUE, TRUE, NULL, NULL, 'Campers swim in Hyles Pond during two free swim periods a day, watched by certified lifeguards. The waterfront also has boating and a Wibit water obstacle course.', NULL, NULL, 2026, 'ea1845d5-2437-5e84-ba6d-e1618a0ac63b', 'camp-clark-plymouth', ST_GeogFromText('SRID=4326;POINT(-70.6673 41.9584)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.oldcolonyymca.org/child-care-camps/camps/camp-clark']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Devereux', 'Devereux School', 'https://www.devereuxschool.org/camp-devereux', NULL, 'Information@devereuxschool.org', '781-631-0029', '44 Smith Street', 'Marblehead', 'MA', '01945', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','nature']::text[], ARRAY['swim instruction','arts and crafts','music','piano','yoga','gymnastics','French','gardening','board games','slip and slide','basketball','soccer']::text[], NULL, 3, 10, NULL, 4, 'Traditional summer day camp at the Devereux School in Marblehead for ages 3 to 10 (through entering 4th grade), running since 1932. Campers get daily swim lessons in a heated pool with two lifeguards, plus art, music, yoga, gymnastics, French, gardening and free play on shaded playgrounds.', 'outdoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, 'Heated outdoor pool, refurbished, with daily swim instruction from two certified lifeguards.', NULL, NULL, 2027, '80d066e0-80e1-519b-be54-9d5ed967430f', 'camp-devereux-marblehead', ST_GeogFromText('SRID=4326;POINT(-70.8578 42.5001)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.devereuxschool.org','https://www.devereuxschool.org/_files/ugd/aa52fd_f6e14822dfc44866ae527934c14abaf8.pdf','https://www.devereuxschool.org/camp-devereux']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Camp at Camp Fire North Shore', 'Camp Fire North Shore', 'https://www.campfirenorthshore.org/summer-camp', NULL, 'mcole@campfirenorthshore.org', '978-745-7200', '2 Cain Road', 'Salem', 'MA', '01970', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['nature','swimming','STEM','sports','adventure']::text[], ARRAY['STEM','sports','team building','skits and songs','nature and outdoor skills','health and fitness','gardening','swim instruction','field trips','hiking','service projects']::text[], NULL, 5, 15, 0, 9, 'Day camp at the Camp Fire North Shore program site in Salem for youth entering grades K to 9, in three groups: Explore Camp (K to 4) with daily swim lessons in an outdoor pool, gardening and STEM; Discovery Camp (5 to 6) with two field trips a week; and Adventure Camp (7 to 9) with two days a week of offsite trips. Camp day 9 to 4, with 7:30 to 5:30 care included.', 'outdoor', NULL, 260, 400, 325, 'week', TRUE, NULL, TRUE, NULL, 'Deposit of $25 per session is non-refundable and non-transferable. Registration fee $20 per child or $30 per family.', 'Staff to child ratio 1:10, with additional supports arranged through the intake process.', 'Outdoor pool, lifeguard supervised, with daily swim instruction included for Explore Camp.', NULL, NULL, 2026, '49d9e4c6-c0e8-5518-88d8-7e831f9c092c', 'camp-fire-north-shore-summer-camp-salem', ST_GeogFromText('SRID=4326;POINT(-70.8967 42.5195)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=2+Cain+Road%2C+Salem%2C+MA&benchmark=Public_AR_Current&format=json','https://www.campfirenorthshore.org/summer-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Club Rec Summer Program', 'City of Woburn Recreation Department', 'https://woburnma.myrec.com/forms/6821_club_recreation_parent_handbook_2026.pdf', NULL, 'rlindstrom@cityofwoburn.com', '781-537-8869', '41 Wyman Street', 'Woburn', 'MA', '01801', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','sports']::text[], ARRAY['gym games','playground','crafts','movement games','swimming','field trips']::text[], NULL, 6, 12, NULL, NULL, 'City run summer day program at Spence Farm in Woburn with gym and outdoor games, crafts, pool swimming and field trips on Tuesdays and Thursdays. Runs Monday to Thursday 9 to 3 and Fridays 9 to 1, with a free bagged lunch offered.', 'both', NULL, 275, 275, 275, 'week', TRUE, NULL, TRUE, TRUE, 'Withdrawals must be in writing. Full refund by May 1, 75% by May 15, 50% by May 29, 25% by June 5. Medical or family emergencies with documentation get a full refund less $10 if made a week ahead.', 'Families should talk with the Recreation Director or Assistant Director before the program starts about any accommodations; school 504 and IEP plans do not carry over. Children must be fully toilet trained.', 'Children are swim tested at their first swim block; those who do not pass stay in the shallow end or wear a Coast Guard approved life jacket supplied by the family. Lifeguards supervise at all times.', NULL, NULL, 2026, 'ac2e97b5-14e0-57aa-b573-16d0533a3a7b', 'club-rec-summer-program-woburn', ST_GeogFromText('SRID=4326;POINT(-71.1523 42.4793)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://woburnma.myrec.com/forms/6805_summer_brochure_2026.pdf','https://woburnma.myrec.com/forms/6821_club_recreation_parent_handbook_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Code & Circuit Summer Sessions', 'Code & Circuit, Inc.', 'https://www.codeandcircuit.org/summer', NULL, 'lori@codeandcircuit.org', NULL, '36 Main St., 2nd floor', 'Amesbury', 'MA', '01913', 'Boston, MA', 'specialty', ARRAY['STEM','technology']::text[], NULL, ARRAY['coding','robotics','LEGO','Minecraft','3D printing','game development','drones','VR','animation']::text[], NULL, NULL, NULL, 0, 12, 'Week long computer science sessions at a nonprofit tech school in downtown Amesbury, Monday to Thursday 9:00 to 2:00, grouped by rising grade from kindergarten to grade 12. Topics include coding, LEGO and VEX robotics, Minecraft engineering, 3D printing, game design and drones.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, NULL, 'Families of neurodivergent learners, or children on an IEP or 504, are asked to email Lori to meet and talk through the best fit; the school says it tries to include all learners.', NULL, NULL, NULL, 2026, '7184e501-b1db-50bc-933a-892eb7147c6d', 'code-and-circuit-summer-sessions-amesbury', ST_GeogFromText('SRID=4326;POINT(-70.9558 42.8513)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=36+Main+St%2C+Amesbury%2C+MA&benchmark=Public_AR_Current&format=json','https://www.codeandcircuit.org/contact','https://www.codeandcircuit.org/summer']::text[], '2026-11-25', '2026-11-25', TRUE),
('Danforth Summer Arts', 'Danforth Art Museum and Art School (Framingham State University)', 'https://danforth.framingham.edu/learn-create/children-summer-arts/', 'https://reg.learningstream.com/view/cal4a.aspx?ek=&ref=&aa=&sid1=&sid2=&as=5&wp=20&tz=&ms=&nav=&cc=&cat1=&cat2=&cat3=&aid=FSU&rf=%20', 'danforthartschool@framingham.edu', '508-215-5116', '100 State Street', 'Framingham', 'MA', '01701', 'Boston, MA', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['drawing','painting','sculpture','fashion illustration','comics','museum tours','student exhibition']::text[], NULL, 5, 14, 0, 8, 'Weekly fine art classes at the Danforth Art Museum''s art school in Framingham for children entering grades K to 8, grouped by grade with a different theme each week. Each week includes a museum tour, a portfolio and a Friday exhibition of student work.', 'both', NULL, 440, 550, 550, 'week', TRUE, NULL, NULL, TRUE, 'Cancellations at least two weeks before the start date get a full refund less a $25 fee; no refunds after that except in emergencies. Transferred registrations get a credit less $25.', 'Families can tell the Summer Arts manager or Art School director about a child''s learning differences ahead of time so staff can adjust.', NULL, NULL, NULL, 2026, 'd8649946-4161-5c38-a2f2-c60b91d878de', 'danforth-summer-arts-framingham', ST_GeogFromText('SRID=4326;POINT(-71.4162 42.2793)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://danforth.framingham.edu/learn-create/children-summer-arts/','https://danforth.framingham.edu/learn-create/scholarships/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Design at Advent Summer Program', 'The Advent School', 'https://www.adventschool.org/summer', 'https://docs.google.com/forms/d/e/1FAIpQLSeXeHgC-GXMGhJ8ljYgoiD-xNLUP9sQ2GVRsZifK1igVq6siw/viewform', 'enrichment@adventschool.org', '(617) 742-0520', '15 Brimmer Street', 'Boston', 'MA', '02108', 'Boston, MA', 'specialty', ARRAY['STEM','arts']::text[], ARRAY['outdoor']::text[], ARRAY['engineering','design thinking','building with recycled materials','tool use','field trips','Design Expo']::text[], NULL, 5, 12, NULL, NULL, 'Two week engineering and design sessions for ages 5 to 12 at The Advent School on Beacon Hill, 8:30 to 4:00. Kids build projects around a theme and take frequent trips to Boston museums, parks and the Esplanade, ending each session with a Design Expo for families.', 'both', NULL, 1250, 1350, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '772923e1-e899-51d9-a5ff-b828d14a664b', 'design-at-advent-summer-program-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.adventschool.org/summer']::text[], '2026-11-25', '2026-11-25', TRUE),
('"e" inc. Summer Science Discovery Program', '"e" inc.', 'https://einc-action.org/science-discovery-camps', NULL, 'sarah.bracken@einc-action.org', '(617) 242-4700', '114 16th Street, Suite 1030', 'Boston', 'MA', '02129', 'Boston, MA', 'specialty', ARRAY['STEM','nature']::text[], NULL, ARRAY['hands-on science projects','plants','water science','weather','earth science','field trips']::text[], NULL, 5, NULL, NULL, NULL, 'A weekly environmental science day camp at the "e" inc. center in the Charlestown Navy Yard for ages 5 and up, grouped by age. Each week has a science theme with hands-on projects and a field trip to places like the Museum of Science or the Arnold Arboretum.', NULL, NULL, 550, 550, 550, 'week', TRUE, NULL, NULL, NULL, 'Full refund for cancellations by June 1, 2026 and 50% by July 1, 2026; later cancellations are considered case by case. No refunds for dismissal, absences or sick days.', NULL, NULL, NULL, NULL, 2026, 'ab2b2ea9-61d4-59d0-9065-0a54f1e91364', 'e-inc-summer-science-discovery-program-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://docs.google.com/document/d/1YegLv752HMlvYTtjCr08SrGZXGdsHcRH4K-sOSv11uo/export?format=txt','https://einc-action.org/science-discovery-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('Esh Circus Arts Youth Summer Program', 'Esh Circus Arts', 'https://www.eshcircusarts.com/youth-summer-program/', 'https://www.eshcircusarts.com/schedule-registration/', 'info@eshcircusarts.com', '(617) 764-0190', NULL, 'Somerville', 'MA', '02143', 'Boston, MA', 'specialty', ARRAY['performing_arts','sports']::text[], NULL, ARRAY['aerial fabric','trapeze','acrobatics','tumbling','juggling','wire walking','hula hooping','clowning']::text[], NULL, 6, 16, NULL, NULL, 'Week long circus camps in Somerville for ages 6 to 16, 9:00 to 3:30, with aerial fabric, trapeze, tumbling, juggling, wire walking and clowning. Circus Survey weeks welcome beginners ages 6 to 14, and the Intensive Week is for ages 8 to 16 with some circus background.', 'indoor', NULL, 895, 895, 895, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '4ee6410e-6025-5264-9cf7-1d66a57b534b', 'esh-circus-arts-youth-summer-program-somerville', ST_GeogFromText('SRID=4326;POINT(-71.0995 42.3876)'), FALSE, FALSE, TRUE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.eshcircusarts.com/contact/','https://www.eshcircusarts.com/youth-summer-program/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Exxcel Gymnastics & Climbing Summer Camp', 'Exxcel Gymnastics & Climbing', 'https://www.exxcel.net/camps/summer-camp/', 'https://www.exxcel.net/register/', 'office@exxcel.net', '617-244-3300', '88 Wells Avenue', 'Newton', 'MA', '02459', 'Boston, MA', 'specialty', ARRAY['sports']::text[], ARRAY['arts','swimming']::text[], ARRAY['gymnastics','climbing','outdoor ropes course','zip lines','bungee','swimming','arts & crafts','games','field trips']::text[], NULL, 3, NULL, NULL, NULL, 'A full day gymnastics and climbing camp at the Exxcel gym in Newton, 9:00 to 3:00, with preschool camp for ages 3 to 5, gymnastics camp for ages 5 and up, and climbing and sports camp for ages 6 and up. Days add a ropes course, zip lines, arts and crafts, a weekly pool trip and a weekly field trip.', 'both', NULL, 744, 835, 835, 'week', TRUE, NULL, FALSE, NULL, 'No credits or refunds for camp cancellations after May 1, 2026. Health forms were due by May 1, 2026, and there is no refund if a camper is restricted for lacking one. A $35 fee applies to late pick-up.', NULL, 'Recreational campers walk to the JCC Outdoor Pool once a week to swim.', NULL, NULL, 2026, 'f7e25e9a-69ca-52e8-8fda-730097b48a65', 'exxcel-gymnastics-and-climbing-summer-camp-newton', ST_GeogFromText('SRID=4326;POINT(-71.2092 42.337)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.exxcel.net/camps/summer-camp/','https://www.exxcel.net/downloads/Summer_Camp/2026/Exxcel_SC_FP_a_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('iD Tech Camps held at MIT', 'iD Tech', 'https://www.idtech.com/locations/massachusetts-summer-camps/cambridge', 'https://www.idtech.com/register#/reg-flow/avail-charts-lock?lid=48&rgnad=true', 'hello@idtech.com', '1-888-709-8324', NULL, 'Cambridge', 'MA', '02139', 'Boston, MA', 'specialty', ARRAY['STEM','technology']::text[], NULL, ARRAY['coding','game development','robotics','3D printing','AI','Minecraft','campus tours','outdoor games']::text[], NULL, 7, 18, NULL, NULL, 'Week long tech day camps for ages 7 to 17 held on the MIT campus in Cambridge, 9:00 to 4:30, in coding, game design, robotics and 3D printing, with recreation breaks on Briggs Field. Teens 13 to 18 can take two week overnight iD Tech Academies in the dorms.', 'both', NULL, 1578, NULL, NULL, 'week', NULL, NULL, NULL, NULL, 'Unlimited free changes up to 28 days before the session. Full refund for cancellations before March 1; after March 1 and at least 28 days before the session, a refund less additional fees.', 'Students of all abilities are welcome; families should contact iD Tech at least three weeks before camp to plan accommodations.', NULL, NULL, NULL, 2027, '9e8849a5-1180-56c9-8b2e-4e571223b766', 'id-tech-at-mit-cambridge', ST_GeogFromText('SRID=4326;POINT(-71.1097 42.3736)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.idtech.com/locations/massachusetts-summer-camps/cambridge']::text[], '2026-11-25', '2026-11-25', TRUE),
('KidsArts Summer Program', 'KidsArts (JP KidsArts)', 'https://www.jpkidsarts.org/summer-2026', 'https://www.jpkidsarts.org/registration', 'info@jpkidsarts.org', '(617) 524-0818', '6 Eliot St, Jamaica Plain', 'Boston', 'MA', '02130', 'Boston, MA', 'day', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['art','music','drama','field trips','showcase performance','free play']::text[], NULL, 5, 12, NULL, NULL, 'A full day summer arts program in Jamaica Plain for ages 5 to 12. Each week kids pick a morning art workshop, work on a group project in the afternoon for a Friday showcase, and take a field trip around the city.', NULL, NULL, NULL, NULL, 545, 'week', NULL, NULL, NULL, TRUE, 'Deposits are non refundable after March 18, 2026 and payments after May 13, 2026, less a $20 processing fee. Registrations cannot be transferred to another child.', NULL, NULL, NULL, NULL, 2026, 'b38c541a-9cae-5601-a694-a992f6effd8f', 'kidsarts-summer-program-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.jpkidsarts.org/summer-2026']::text[], '2026-11-25', '2026-11-25', TRUE),
('Meadow Breeze Day Camp', 'Lexington Christian Academy', 'https://lca.edu/mbdc-day/', 'https://lcasummer.campbrainregistration.com/', 'summer@lca.edu', '781-766-2162 ext. 351', '48 Bartlett Avenue', 'Lexington', 'MA', '02420', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['archery','music','swimming','drama','tennis','arts and crafts','indoor and outdoor sports','rock wall climbing']::text[], NULL, NULL, NULL, 0, 8, 'Weekly day camp on the Lexington Christian Academy campus for children entering kindergarten through grade 8. Days run 8 to 3 and include a swim class and free swim, plus archery, tennis, drama, music, crafts, sports and the climbing wall.', 'both', NULL, 504, 630, 630, 'week', TRUE, NULL, FALSE, NULL, 'A $35 registration fee and a $200 deposit per session apply. Cancel by February 1 for a full refund less the registration fee; cancel February 2 to April 1 for a refund less the registration fee and deposit. After April 1 there are no refunds, but a session can be transferred.', NULL, 'Daily extended swim period with a skill based swim class and free swim. Each camper gets a swim assessment based on American Red Cross standards on arrival.', NULL, NULL, 2027, '3718d393-8a6d-54af-b352-0e69b57e9a5f', 'meadow-breeze-day-camp-lexington', ST_GeogFromText('SRID=4326;POINT(-71.2245 42.4473)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://lca.edu/dates-rates/','https://lca.edu/mbdc-day/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Medford Recreation Summer Park Program', 'City of Medford Recreation Department', 'https://medfordma.myrec.com/forms/6232_family_handbook_2026.pdf', NULL, 'medfordrecreation@medford-ma.gov', '781-393-2486', '449 Main Street', 'Medford', 'MA', '02155', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','nature']::text[], ARRAY['swimming','swim lessons','arts and crafts','sports','games','nature','science','field trips','cooking']::text[], NULL, 6, 12, 1, 6, 'City run summer day program for grades 1 to 6 at Tufts Park and pool in Medford, with a weekly theme, daily swimming and Red Cross swim lessons, crafts, sports and a weekly field trip for each group.', 'both', NULL, 250, 250, 250, 'week', NULL, NULL, FALSE, TRUE, 'No refunds for cancellations. Household credits only before April 1, 2026; cancellations must be in writing. No refunds or credits for missed days.', 'Families can request accommodations through the Inclusion Service Request Form on the recreation website; the program manager follows up by phone.', 'Daily pool time at Tufts pool with city lifeguards on duty. Children are placed in Red Cross levels 1 to 4; the deep end test is one pool length and 30 seconds of treading water. Non-swimmers can wear a life jacket or be limited to the wading pool.', NULL, NULL, 2026, 'aff02aab-3839-590f-bbba-e6853298a23b', 'medford-recreation-summer-park-program-medford', ST_GeogFromText('SRID=4326;POINT(-71.1062 42.4184)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://medfordma.myrec.com/forms/6232_family_handbook_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Natick Boathouse Summer Camps', 'Adventures Unbound Commonwealth Collection', 'https://commonwealth.adventuresunbound.com/all-activities/camps/', 'https://www.ultracamp.com/info/upcomingsessions.aspx?idCamp=511&campCode=bib&idLocation=1878', NULL, NULL, '25 Commonwealth Road', 'Natick', 'MA', '01760', 'Boston, MA', 'specialty', ARRAY['sailing','outdoor']::text[], ARRAY['adventure']::text[], ARRAY['sailing','kayaking','canoeing','stand up paddleboarding','boating safety','knots']::text[], NULL, 8, 15, NULL, NULL, 'Week long boating day camps on Lake Cochituate at the Natick Boathouse for ages 8 to 15. Campers spend about half the day sailing and the rest kayaking, canoeing and paddleboarding, with a three week Boating for Teens program for ages 13 to 15.', 'outdoor', NULL, 355, 580, 580, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'Most counselors are Red Cross certified lifeguards, and the camp keeps one lifeguard or instructor for every 7 campers. Campers stay off the water on days when wind makes it unsafe and work on boating skills on shore.', NULL, NULL, 2027, 'd69af9f3-98d2-53ab-91de-41c3fc13e137', 'natick-boathouse-summer-camps-natick', ST_GeogFromText('SRID=4326;POINT(-71.3495 42.2834)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://commonwealth.adventuresunbound.com/all-activities/camps/']::text[], '2026-11-25', '2026-11-25', TRUE),
('NEOC (New England Outdoor Camps)', 'New England Outdoor Camps, LLC', 'https://www.campneoc.com/', 'https://www.campneoc.com/register', 'info@campneoc.com', '781-235-8765', '900 Washington Street', 'Wellesley', 'MA', '02482', 'Boston, MA', 'day', ARRAY['outdoor','nature']::text[], ARRAY['adventure','arts','sports','STEM','leadership']::text[], ARRAY['nature exploration','bug hunting','outdoor games','afternoon sign up activities']::text[], NULL, 3, 16, NULL, 10, 'Outdoor day camp at the Gardens at Elm Bank in Wellesley, with fields, woods, trails and Charles River access, for children from age 3 through entering 10th grade. Camp runs 9 to 4 with no technology; campers choose afternoon activities, and families can add busing, early drop off from 8 and extended day to 6.', 'outdoor', NULL, 821, 872, 872, 'week', TRUE, TRUE, FALSE, NULL, 'Full refund up to January 20 (or within 24 hours of registering); then NEOC credit of 100% to February 10, 75% to March 17, 50% to April 21 and 25% to May 19; nothing after May 19. The $100 per week deposit is refundable until January 20.', NULL, NULL, NULL, NULL, 2027, '7fc2e5b4-5c75-5d13-9c34-bc144d858076', 'neoc-new-england-outdoor-camps-wellesley', ST_GeogFromText('SRID=4326;POINT(-71.2923 42.2968)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.campneoc.com/about','https://www.campneoc.com/contact','https://www.campneoc.com/details/pricing','https://www.campneoc.com/faq','https://www.campneoc.com/policies','https://www.campneoc.com/register','https://www.campneoc.com/services/bus','https://www.campneoc.com/services/extendedday']::text[], '2026-11-25', '2026-11-25', TRUE),
('Penguin Coding School Summer Sessions, Brookline', 'Penguin Coding School', 'https://penguincodingschool.com/summer-coding-stem-robotics-kids-camp-brookline-massachusetts', NULL, 'info@penguincodingschool.com', '(781) 824-2262', '43 Harvard Street', 'Brookline', 'MA', '02445', 'Boston, MA', 'specialty', ARRAY['STEM','technology']::text[], ARRAY['leadership']::text[], ARRAY['coding','Minecraft Education','Python','LEGO robotics','3D printing','science experiments','outdoor time','counselor in training']::text[], NULL, 6, 18, NULL, NULL, 'Weekly coding and robotics day camp in Brookline, 9:00 to 3:00, with Minecraft coding for ages 6 to 9, Python for ages 9 to 12 and a STEM counselor in training program for ages 13 to 18. Days mix coding lessons with LEGO robotics, 3D printing, science experiments and outdoor time.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '8de38a05-270e-5a11-900a-6298cd873bba', 'penguin-coding-school-summer-sessions-brookline', ST_GeogFromText('SRID=4326;POINT(-71.1212 42.3318)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://penguincodingschool.com/summer-coding-stem-robotics-kids-camp-brookline-massachusetts']::text[], '2026-11-25', '2026-11-25', TRUE),
('Somertime Day Program', 'Somerville Parks & Recreation', 'https://somervillema.myrec.com/documents/somertime_handbook_2026.pdf', NULL, NULL, '617-625-6600 ext. 2980', '177 Powderhouse Boulevard', 'Somerville', 'MA', '02144', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts']::text[], ARRAY['games','arts and crafts','softball','kickball','volleyball','basketball','swimming','field trips']::text[], NULL, 5, 13, NULL, NULL, 'City summer day program for children ages 5 to 13, based at the West Somerville Neighborhood School, with games, crafts, low key sports, pool time and field trips. Runs in one week sessions from late June to mid August.', 'both', NULL, 400, 400, 400, 'week', NULL, NULL, NULL, NULL, 'A registration fee of half the weekly price ($100 resident, $200 non-resident) per child per week is due with the application and is not refundable. No refund for the rest of a week if a child leaves, is removed or is suspended.', NULL, 'Every child takes a swim test before using the big pool at Dilboy. Lifeguards and certified swim instructors are at the pool.', NULL, NULL, 2026, 'c1f1b8ab-7497-5f32-bd29-e204ba50da2a', 'somertime-day-program-somerville', ST_GeogFromText('SRID=4326;POINT(-71.0995 42.3876)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://somervillema.myrec.com/documents/somertime_handbook_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Stage Pop Stars Summer Camp', 'Stage Music Center', 'https://stagemusiccenter.squarespace.com/summer-camps-children-winchester-ma-lp', 'https://stagemusiccenter.squarespace.com/summer-camp-ecomm-winchester-ma', 'info@stagemusiccenter.com', '781-570-2556', '50 Cross Street', 'Winchester', 'MA', '01890', 'Boston, MA', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['singing','choreography','improv acting','storytelling','arts and crafts','outdoor games','showcase']::text[], NULL, 6, 12, NULL, NULL, 'Weekly music and performing arts day camp for ages 6 to 12 at Stage Music Center in Winchester. Each themed week mixes group singing, choreography, improv and crafts with outdoor games, ending in a Friday showcase for families.', 'both', NULL, 575, 575, 575, 'week', NULL, NULL, FALSE, NULL, 'Cancellations by May 15 get a full refund minus processing fees (about $30 per registration). After May 15, no refund but a full credit toward lessons, classes or camps. Requests must be in writing.', NULL, NULL, NULL, NULL, 2027, 'c1a12409-1548-5658-baca-74a99313830e', 'stage-pop-stars-summer-camp-winchester', ST_GeogFromText('SRID=4326;POINT(-71.137 42.4523)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://stagemusiccenter.squarespace.com/summer-camp-ecomm-winchester-ma','https://stagemusiccenter.squarespace.com/summer-camps-children-winchester-ma-lp']::text[], '2026-11-25', '2026-11-25', TRUE),
('STEM Camp at EHS', 'Epstein Hillel School, with JCC of the North Shore Camp Simchah', 'https://epsteinhillel.org/ehs-summer-stem-camp/', 'https://jccns.org/summer-camp/camp-simchah-specialty-ehs-stem-camp/', 'rkaren@epsteinhillel.org', '781-639-2880 x201', '6 Community Road', 'Marblehead', 'MA', '01945', 'Boston, MA', 'specialty', ARRAY['STEM']::text[], ARRAY['swimming']::text[], ARRAY['VEX robotics','model rocketry','laser cutting','3D printing','engineering challenges','science experiments','swimming','outdoor play']::text[], NULL, NULL, NULL, 3, 7, 'A weekly STEM day camp for children entering grades 3 to 7 in the Innovation Center at Epstein Hillel School in Marblehead, 9:15 to 4:00. Weeks alternate between VEX robotics and model rocketry, with time on the school''s fields and at the JCC outdoor pool.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, 'Campers have aquatics time at the JCC outdoor pool complex.', NULL, NULL, 2026, '6671dfc1-d4be-541b-95de-6093e350c29c', 'stem-camp-at-ehs-marblehead', ST_GeogFromText('SRID=4326;POINT(-70.8578 42.5001)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://epsteinhillel.org/ehs-summer-stem-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Adventure', 'Wayland Recreation Department', 'https://www.wayland.ma.us/1322/Summer-Adventure', 'https://waylandrec.activityreg.com/clientpage_t2.wcs', NULL, NULL, '264 Old Connecticut Path', 'Wayland', 'MA', '01778', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming']::text[], ARRAY['theme days','field trips','swimming','town beach','indoor games','outdoor games']::text[], NULL, 5, 11, 0, 5, 'Town recreation day camp at Wayland High School for children entering kindergarten to grade 5, grouped by grade, with weekly themes and dress-up days, one field trip a week, two walks to the community pool and a trip to the Town Beach.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'Written withdrawals: free before March 15; then credit or refund less $25 to $50 depending on the date; no credit or refund within ten business days of the camp week without a doctor''s note. No proration or make-up days.', NULL, 'Campers who want to swim at the Town Beach or community pool take a swim test or wear a fitted life jacket, which camp provides. Extra lifeguards supervise swim times.', NULL, NULL, 2027, 'd0c93a3f-fd16-5209-979f-7910d2032980', 'summer-adventure-wayland', ST_GeogFromText('SRID=4326;POINT(-71.3614 42.3626)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.wayland.ma.us/1322/Summer-Adventure','https://www.wayland.ma.us/1326/What-to-Bring','https://www.wayland.ma.us/1328/Swim-Tests','https://www.wayland.ma.us/1329/Register-for-Camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer at BC High', 'Boston College High School', 'https://www.bchigh.edu/summer-camps', 'https://bchighsummer.campbrainregistration.com/', 'feloney@bchigh.edu', '617-474-5181', '150 Morrissey Blvd.', 'Boston', 'MA', '02125', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','STEM','academic']::text[], ARRAY['swim lessons','arts & crafts','organized sports','tennis','scavenger hunts','legos','water games','tie dye','strength and conditioning','baseball','basketball','soccer','coding','robotics','minecraft','cooking','animation']::text[], NULL, 5, 18, NULL, NULL, 'Summer programs on BC High''s Dorchester campus: a coed day camp for ages 5 to 9 with swim lessons and sports, a themed adventure week program for ages 10 to 14, plus boys'' sports camps, coding, art and academic courses.', 'both', NULL, 600, 1200, 600, 'session', NULL, FALSE, FALSE, NULL, '$100 per session deposit is non refundable. Withdraw before June 1, 2027 for a refund of everything else; no refunds after June 1, 2027.', NULL, NULL, NULL, NULL, 2027, '5c883204-d235-508e-9f8b-173985b6f3e8', 'summer-at-bc-high-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bchigh.edu/summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer@Riverbend and Riverbend Adventure Camp', 'Riverbend School', 'https://riverbendschool.org/our-programs/summer-riverbend/', 'https://summeratriverbend.campbrainregistration.com/', 'info@rvbs.org', '508-655-7333', '33 Eliot Street', 'Natick', 'MA', '01760', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['outdoor','nature','sports','arts','STEM']::text[], ARRAY['water play','sports','arts and crafts','outdoor exploration','music','games','STEM','nature walks','hikes','field trips']::text[], NULL, 2, 12, NULL, 6, 'Summer programs on Riverbend School''s Montessori campus in Natick, 9 to 3. Summer@Riverbend serves ages 2 to rising kindergarten with half or full days of water play, crafts, music and outdoor play; Adventure Camp, for rising 1st to 6th graders, adds hikes to the Natick waterfall and Elm Bank, STEM, sports and two field trips a week.', 'both', NULL, 420, 625, 625, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '8088b185-aa0c-5cb1-b0ed-65ae0b751c7e', 'summer-at-riverbend-natick', ST_GeogFromText('SRID=4326;POINT(-71.3495 42.2834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://riverbendschool.org/our-programs/summer-riverbend/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer at Tower', 'Tower School', 'https://www.towerschool.org/summer/overview', 'https://summerattower.campbrainregistration.com/', 'summer@towerschool.org', '781-631-5800 x393', '75 West Shore Drive', 'Marblehead', 'MA', '01945', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','STEM']::text[], ARRAY['swim lessons','free swim','themed weeks','crafts','science experiments','design workshop','field trips','leaders in training']::text[], NULL, NULL, 15, NULL, 9, 'Day camp on Tower School''s 8 acre campus in Marblehead for ages 2 years 9 months through entering grade 9, in nine one week themed sessions. Younger groups choose half days (8 to 1) or full days (8 to 4) with pool swim lessons; older campers get field trips, a three week design workshop and a leaders in training program.', 'both', NULL, 317, 577, 525, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 'https://www.towerschool.org/summer/overview', 2026, '162ad114-14df-595f-ab89-0d9133b09d44', 'summer-at-tower-marblehead', ST_GeogFromText('SRID=4326;POINT(-70.8578 42.5001)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.towerschool.org/summer/explorers','https://www.towerschool.org/summer/overview','https://www.towerschool.org/summer/pathfinders']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Music @ Tufts', 'Tufts University Department of Music', 'https://as.tufts.edu/music/community-programs/summer-music', 'https://docs.google.com/forms/d/e/1FAIpQLSccOCXPVmz-zqxf6XhR7XvvYR7kVXQdWpKn8jn6hvY7U7kROA/viewform', 'summermusic@tufts.edu', '617-627-3564', '20 Talbot Avenue', 'Medford', 'MA', '02155', 'Boston, MA', 'specialty', ARRAY['performing_arts']::text[], ARRAY['arts']::text[], ARRAY['singing','african drumming','piano','violin','guitar','ukulele','music and movement','outdoor games']::text[], NULL, 7, 12, NULL, NULL, 'Two week music day program for ages 7 to 12 in Tufts University''s Granoff Music Center in Medford. Children take small group instrument classes, singing, drumming and music and movement, eat lunch in the dining hall and finish with a family concert.', 'both', NULL, 1200, 1200, NULL, 'session', TRUE, NULL, TRUE, TRUE, 'A $150 deposit is due at registration and is not refundable. The $1,050 balance is due by June 15, 2027; registrations after that date pay a $50 late fee if space remains.', NULL, NULL, NULL, NULL, 2027, 'b7586d7b-6c24-5369-ba0d-4eb7d0cbf0a3', 'summer-music-at-tufts-medford', ST_GeogFromText('SRID=4326;POINT(-71.1062 42.4184)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://as.tufts.edu/music/community-programs/summer-music']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Science Academy', 'Bridgewater State University, Center for the Advancement of STEM Education (CASE)', 'https://www.bridgew.edu/center/case/science-academy', 'https://secure.touchnet.com/C20026_ustores/web/store_main.jsp?STOREID=17&SINGLESTORE=true', 'casebsu@bridgew.edu', '508-531-2575', '131 Summer Street', 'Bridgewater', 'MA', '02325', 'Boston, MA', 'specialty', ARRAY['STEM']::text[], ARRAY['academic','technology']::text[], ARRAY['dissection','suturing','microscopy','electrophoresis','cybersecurity','sphero robots','forensics','DNA fingerprinting']::text[], NULL, 12, 17, 7, 12, 'One week in person STEM classes at Bridgewater State University, 8:30 to 2:30, held in the science and math center. High school students in grades 9 to 11 study the human body from a medical angle; middle schoolers in grades 6 to 8 take cybersecurity classes with Sphero robots or a forensics class.', 'indoor', NULL, 300, 400, NULL, 'session', NULL, FALSE, FALSE, TRUE, 'Written cancellation more than one month before the program gets a refund less a $50 fee; more than two weeks before gets 50% less the $50 fee; no refund after that, or if the required CampDocs forms are not in two weeks before.', NULL, NULL, NULL, NULL, 2027, 'c03fed1d-6042-50fb-9248-cc9074266253', 'summer-science-academy-bridgewater', ST_GeogFromText('SRID=4326;POINT(-70.975 41.9904)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bridgew.edu/center/case/science-academy']::text[], '2026-11-25', '2026-11-25', TRUE),
('SummerScape', 'North Reading Parks & Recreation', 'https://northreadingma.myrec.com/forms/6007_spring_summer_2026.pdf', NULL, NULL, '978-664-6016', '298 Haverhill Street', 'North Reading', 'MA', '01864', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['sports','arts']::text[], ARRAY['theme days','games','crafts','music','nature activities','field and gym games','talent show','water day','waterslide','relay games','touch a truck','weekly entertainers']::text[], NULL, 6, 14, 1, 8, 'Town summer day camp at the J. Turner Hood Elementary School in North Reading for children entering grades 1 to 8, weekdays 9 to 3 for six themed weeks. Days include theme day games, visiting entertainers on Wednesdays, water games and a waterslide on Thursdays, and relays on Fridays; campers bring lunch and snack.', 'both', NULL, 250, 250, 250, 'week', TRUE, NULL, FALSE, TRUE, 'No refunds, transfers or credits. One time $35 membership fee; one week minimum, registered by noon the Friday before.', 'A half day option ($125 a week) is available for children on Individual Education Plans; call to register.', NULL, NULL, NULL, 2026, 'bc010743-0e1f-5e18-b37e-17646ed18a1a', 'summerscape-north-reading', ST_GeogFromText('SRID=4326;POINT(-71.0787 42.5751)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://northreadingma.myrec.com/forms/6007_spring_summer_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Adventure Day Camp', 'Ridgefield Parks & Recreation', 'https://www.ridgefieldparksandrec.org/223/Adventure-Day-Camp', NULL, 'campcoor@ridgefieldct.gov', '203-431-2755', 'Ridgefield Recreation Center, 195 Danbury Road', 'Ridgefield', 'CT', '06877', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['sports','arts','nature','swimming']::text[], ARRAY['sports','games','arts and crafts','water fun','nature exploration','team building','gaga','swimming','beach trips','field trips']::text[], NULL, 4, NULL, NULL, 7, 'A town day camp at the Ridgefield Recreation Center for 4 year olds through children entering grade 7, in one week sessions from 9 am to 4 pm. Groups by grade play sports and games, do art, explore the trails and pond, use the spray area and indoor pool, and older groups go to Martin Park Beach and on field trips.', 'both', NULL, 308, 363, 363, 'week', TRUE, NULL, FALSE, NULL, 'Refundable up to three weeks before the session starts, with administrative approval and a $25 per week fee; medical absences with a doctor''s note refunded pro rata. No refunds for cancelled field trips.', NULL, 'Older groups swim in the indoor pool with counselors in the water and lifeguards on duty; weekly swim tests. Grades 2 and up go to Martin Park Beach on Tuesdays. The 4 year olds have outdoor water play only.', NULL, NULL, 2026, '71eed9fb-00bb-53d8-aaff-5b93940d61a0', 'adventure-day-camp-ridgefield', ST_GeogFromText('SRID=4326;POINT(-73.4998 41.3177)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ridgefieldparksandrec.org/223/Adventure-Day-Camp','https://www.ridgefieldparksandrec.org/228/Trailblazers-entering-grade-3','https://www.ridgefieldparksandrec.org/DocumentCenter/View/226']::text[], '2026-11-25', '2026-11-25', TRUE),
('Adventure Day Camp', 'Southbury Parks and Recreation', 'https://southburyct.myrec.com/documents/2026_adc_parent_handbook.pdf', NULL, 'adcdirector@southbury-ct.gov', '203-262-0633', 'Ballantine Park Pavilion, 611 Old Field Road', 'Southbury', 'CT', '06488', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['sports','swimming','arts']::text[], ARRAY['swim lessons','swimming','arts and crafts','basketball','pickleball','gaga','kickball','soccer','capture the flag','ultimate frisbee','volleyball','board games','field trips']::text[], NULL, NULL, NULL, NULL, NULL, 'A town day camp at the Ballantine Park pavilion in Southbury, weekdays 8:30 am to 4 pm in weekly sessions from July 6 to August 14. Campers are grouped by grade, play sports and games, do art, have a weekly swim lesson and camper only pool time, meet entertainers on Tuesdays and take a field trip most Thursdays.', 'outdoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'Full refund for cancellations before registration closes (the Friday two weeks before the camp week); 25% fee after that; 50% fee within seven days of the week''s start. No refunds for dismissals.', NULL, 'Each week includes a swim lesson and pool time reserved for campers at the Ballantine Park pool, weather permitting; none on field trip days.', NULL, NULL, 2026, 'aa99db9f-8a12-5d63-a72d-7e210a3ffea3', 'adventure-day-camp-southbury', ST_GeogFromText('SRID=4326;POINT(-73.2297 41.476)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=611+Old+Field+Road%2C+Southbury%2C+CT&benchmark=Public_AR_Current&format=json','https://southburyct.myrec.com/documents/2026_adc_parent_handbook.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Artivity @ The Bushnell', 'The Bushnell Center for the Performing Arts', 'https://www.bushnell.org/education/community-engagement/artivity', 'https://www.bushnell.org/events/detail/artivity-sail-into-summer-7-13-7-17-26-eduartsuma', NULL, '860-987-5900', '166 Capitol Avenue', 'Hartford', 'CT', '06106', 'Connecticut', 'specialty', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['puppetry','sewing','visual art','textiles','drumming','jewelry making','yoga','music making']::text[], NULL, 7, 14, NULL, NULL, 'A half day arts program at The Bushnell in Hartford for ages 7 to 14, 9 am to 12:15 pm for a week. Teaching artists lead hands on workshops such as puppetry, sewing, drumming, jewelry making, yoga and music, with offerings that vary by week.', 'indoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'b477d184-a0bb-5ffa-a3ed-09dc32b74726', 'artivity-at-the-bushnell-hartford', ST_GeogFromText('SRID=4326;POINT(-72.6851 41.7658)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.bushnell.org/education/community-engagement/artivity','https://www.bushnell.org/events/detail/artivity-sail-into-summer-7-13-7-17-26-eduartsuma']::text[], '2026-11-25', '2026-11-25', TRUE),
('Boys & Girls Club of Milford Summer Camp', 'Boys & Girls Club of Milford', 'https://boysandgirlsclubofmilford.com/summer-at-the-club/', 'https://bgcmilford.my.site.com/portal/s/login/?ec=302&startURL=%2Fportal%2Fs%2F', 'info@boysandgirlsclubofmilford.com', '203-713-8055', '59 Devonshire Road', 'Milford', 'CT', '06460', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','sports']::text[], ARRAY['themed weeks','outdoor recreation','arts and crafts','STEM','group games','team building','field trips']::text[], NULL, NULL, NULL, 0, 8, 'A weekly summer day camp run by the Boys & Girls Club of Milford at its Simon Lake site on Devonshire Road, for children entering kindergarten through 8th grade, 9 am to 5:30 pm. Weeks have themes, outdoor recreation, arts and crafts, STEM and team games, with optional field trips at extra cost.', NULL, NULL, 250, 250, 250, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '535c1823-b27c-5a6e-a4c5-5c2f85b1b267', 'boys-and-girls-club-of-milford-summer-camp-milford', ST_GeogFromText('SRID=4326;POINT(-73.0573 41.2223)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://boysandgirlsclubofmilford.com/summer-at-the-club/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Aldrich', 'The Aldrich Contemporary Art Museum', 'https://thealdrich.org/learn/camp-aldrich', NULL, NULL, '203-438-4519', '258 Main Street', 'Ridgefield', 'CT', '06877', 'Connecticut', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['art making','gallery tours','sculpture garden','outdoor play']::text[], NULL, NULL, NULL, 1, 6, 'A week long art day camp at The Aldrich museum in Ridgefield, 9:30 am to 4 pm. Campers tour the galleries and Sculpture Garden, make art with a teaching artist, and show their work to families at a Friday evening celebration. Each week is for one grade band.', 'both', NULL, 530, 530, 530, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '9a735b3b-520e-5832-a880-457b13725f99', 'camp-aldrich-ridgefield', ST_GeogFromText('SRID=4326;POINT(-73.4998 41.3177)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://thealdrich.org/learn/camp-aldrich']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Bart', 'Bartlett Arboretum & Gardens', 'https://www.bartlettarboretum.org/summer-camp', NULL, 'edu@bartlettarboretum.org', NULL, '151 Brookdale Road', 'Stamford', 'CT', '06903', 'Connecticut', 'day', ARRAY['nature']::text[], ARRAY['STEM','outdoor','arts']::text[], ARRAY['stream study','pond netting','birding','hiking','crafts','egg drop','fossil digging','orienteering','shelter building','water play']::text[], NULL, 5, 12, 0, 6, 'Nature day camp on the Bartlett Arboretum''s 93 acres of forest and gardens in Stamford for children entering kindergarten to grade 6, in two age groups. Each week has a nature theme with hands-on science, crafts and outdoor play.', 'both', NULL, 435, 475, 475, 'week', TRUE, NULL, FALSE, TRUE, 'Withdrawals by email. Full refund less $25 per camper on or before May 4, 2026; 50% less $25 from May 5 to June 1; no refund from June 2 except approved emergencies. No refunds for missed days.', NULL, NULL, NULL, NULL, 2026, '0436010f-73b2-5b3c-bdb8-e76bb2b86e91', 'camp-bart-stamford', ST_GeogFromText('SRID=4326;POINT(-73.5387 41.0534)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.bartlettarboretum.org/summer-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp SoundWaters', 'SoundWaters', 'https://soundwaters.org/youth-programs/summer-camp/', 'https://campscui.active.com/orgs/SoundWaters', 'camp@soundwaters.org', '203-252-3253', '1281 Cove Road', 'Stamford', 'CT', '06902', 'Connecticut', 'day', ARRAY['sailing','nature']::text[], ARRAY['swimming','STEM','outdoor']::text[], ARRAY['sailing','swimming','animal encounters','science experiments','water exploration','fishing','boogie boarding','art','boat race','talent show']::text[], NULL, 6, 15, 1, 9, 'Sailing and marine science day camp at SoundWaters'' Coastal Center in Cove Island Park, Stamford, for children entering grades 1 to 9, grouped by grade. Each themed week mixes sailing on Holly Pond or Long Island Sound with swimming, animal encounters, experiments and art; older groups spend more of the day sailing.', 'both', NULL, 550, 675, NULL, 'week', TRUE, NULL, FALSE, TRUE, 'A $150 per session deposit is due at registration and is not refundable. The balance is charged May 1, 2027; refunds less the deposit until May 1, none after.', NULL, 'Staff include certified sailing instructors and lifeguards; younger groups swim at the beach daily. Sharks (grades 7 to 9) sail on Long Island Sound with US Sailing certified instructors.', NULL, NULL, 2027, '8c350097-4c7e-5ef6-bc8a-c3d55ca08b33', 'camp-soundwaters-stamford', ST_GeogFromText('SRID=4326;POINT(-73.5387 41.0534)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://soundwaters.org/youth-programs/summer-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Wangumbaug', 'Town of Coventry Parks and Recreation', 'https://www.coventry-ct.gov/616/Camp-Wangumbaug', 'https://secure.rec1.com/CT/coventry-ct/catalog', 'rec@coventry-ct.gov', '860-968-7700', 'Patriots Park, 124 Lake Street', 'Coventry', 'CT', '06238', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['swimming','arts and crafts','sports','teambuilding','group games','field trips','special guest performers']::text[], NULL, NULL, NULL, 0, 8, 'Coventry''s town day camp at Patriots Park for children entering kindergarten through 8th grade, 9 am to 4 pm by the week. Campers rotate through arts and crafts, sports, teambuilding and lifeguarded swimming each day, with optional field trips for grades 2 to 8.', 'both', NULL, 250, 250, 250, 'week', TRUE, NULL, FALSE, TRUE, 'The $25 weekly deposit is not refundable. No refunds for cancellations after June 8, and no refunds or credits for missed weeks without a doctor''s note. Cancellations must be made in writing by email.', NULL, 'Swimming is a daily rotation supervised by lifeguards; campers stay in water no deeper than armpit height and may wear life vests.', NULL, NULL, 2026, '7940eae4-a7a2-593d-86f9-065ca2d8c289', 'camp-wangumbaug-coventry', ST_GeogFromText('SRID=4326;POINT(-72.3438 41.7802)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.coventry-ct.gov/616/Camp-Wangumbaug','https://www.coventry-ct.gov/DocumentCenter/View/10222/Parent-Handbook26','https://www.coventry-ct.gov/DocumentCenter/View/10238/Camp-FAQ']::text[], '2026-11-25', '2026-11-25', TRUE),
('Newtown Community Center Summer Day Camp', 'Town of Newtown (Newtown Community Center)', 'https://online.flippingbook.com/view/544882117', NULL, 'info.ncc@newtown-ct.gov', '(203) 270-4349', '8 Simpson St', 'Newtown', 'CT', '06470', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming','nature']::text[], ARRAY['athletics','arts and crafts','nature exploration','team building games','swimming','hiking','cooking','indoor turf games','special events']::text[], NULL, 5, 12, 0, 6, 'Full day camp at the Newtown Community Center and the Fairfield Hills campus for children entering kindergarten to grade 6. Each week has a theme, with sports, crafts, nature walks, pool time and a weekly visit to Newtown Youth Academy for turf and court games.', 'both', NULL, 245, NULL, 245, 'week', TRUE, NULL, FALSE, NULL, 'Withdrawing from a full week earns a credit for future use; a full refund needs a doctor''s note. No refunds or credits for single missed days. A $100 deposit per week is not refundable.', NULL, 'Swim test on the first day; non swimmers wear a life vest. No formal swim lessons. Indoor pool at the community center.', NULL, NULL, 2026, 'b3286a1f-64c9-5a05-9e1f-44c7051c4e8a', 'newtown-community-center-summer-day-camp-newtown', ST_GeogFromText('SRID=4326;POINT(-73.294 41.3995)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://online.flippingbook.com/view/544882117']::text[], '2026-11-25', '2026-11-25', TRUE),
('OSPR Summer Camp and Middle School Summer Camp', 'Old Saybrook Parks & Recreation', 'https://oldsaybrookct.myrec.com/forms/5579_springsummer_2026.pdf', NULL, NULL, '860-395-3152', 'The Rec, 308 Main Street', 'Old Saybrook', 'CT', '06475', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['sports','arts','nature']::text[], ARRAY['nature','arts and crafts','sports','outdoor play','beach trips','mini golf','entertainers','water day','field trips']::text[], NULL, NULL, NULL, 1, 8, 'Town run weekly day camps at The Rec in Old Saybrook, 9 am to 4 pm: OSPR Summer Camp for children entering grades 1 to 4, and Middle School Summer Camp for grades 5 to 8 with a weekly field trip. Days include nature, arts and crafts, sports, beach and mini golf outings, entertainers and a water day.', NULL, NULL, 130, 185, NULL, 'week', TRUE, NULL, FALSE, NULL, 'Full refund if requested one week before the program starts; 50% refund if cancelled less than one week before; no refunds once the program starts. Full refund if the department cancels.', NULL, NULL, NULL, NULL, 2026, '2c36c491-6abf-585c-9762-a977aa0401df', 'ospr-summer-camp-and-middle-school-summer-camp-old-saybrook', ST_GeogFromText('SRID=4326;POINT(-72.3836 41.2935)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://oldsaybrookct.myrec.com/forms/5579_springsummer_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Players Camp (Westville)', 'Elm Shakespeare Company', 'https://www.elmshakespeare.org/education/players-camp', NULL, 'sarah@elmshakespeare.org', NULL, 'Congregation Beth El-Keser Israel, 85 Harrison Street', 'New Haven', 'CT', '06515', 'Connecticut', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['acting','stagecraft','storytelling','performance']::text[], NULL, 7, 13, NULL, NULL, 'A two week indoor theater camp for ages 7 to 13 run by Elm Shakespeare Company at Congregation Beth El-Keser Israel in the Westville part of New Haven. Campers learn acting, stagecraft and storytelling with theater professionals and finish with a performance tied to the company''s summer Shakespeare production.', 'indoor', NULL, 670, 670, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '02a21591-c4ef-5000-8ebc-611b7f56325c', 'players-camp-westville-new-haven', ST_GeogFromText('SRID=4326;POINT(-72.9251 41.3082)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=85+Harrison+Street%2C+New+Haven%2C+CT&benchmark=Public_AR_Current&format=json','https://www.elmshakespeare.org/education/players-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer@FCDS', 'Fairfield Country Day School', 'https://www.fairfieldcountryday.org/summerfcds', 'https://summerfcds.campbrainregistration.com/', 'summer@fairfieldcountryday.org', '203-259-2723', '2970 Bronson Road', 'Fairfield', 'CT', '06824', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['sports','arts and crafts','visual arts','culinary arts','swimming','technology','game rooms','soccer','dodgeball','kickball','capture the flag','floor hockey','basketball']::text[], 'coed', NULL, NULL, 0, 6, 'A coed day camp on the 20 acre Fairfield Country Day School campus for children entering kindergarten through 6th grade, in week long sessions. Campers play sports, do arts and crafts and cooking, use the game rooms and technology, and swim daily in the school pool.', 'both', NULL, 565, 595, 595, 'week', NULL, NULL, NULL, NULL, 'The $125 weekly deposit is not refundable. Written cancellation was due by March 31, 2026; after that the fee is not refunded or prorated for missed sessions or days.', NULL, 'All campers swim daily, weather permitting, with full time lifeguards. Swimming is encouraged but not required, flotation devices are not allowed, and no swim lessons are given.', NULL, NULL, 2026, '40ef7d05-6fd4-50b3-9e6b-6083acc66a74', 'summer-at-fcds-fairfield', ST_GeogFromText('SRID=4326;POINT(-73.2637 41.1418)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.fairfieldcountryday.org/summerfcds','https://www.fairfieldcountryday.org/summerfcds/faqs']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Fun Camp', 'Bristol Parks, Recreation, Youth and Community Services', 'https://bristolct.myrec.com/documents/2026_summer_fun_camp_gr_13_weekly_calendar.pdf', NULL, NULL, NULL, 'Bristol Eastern High School, 632 King Street', 'Bristol', 'CT', '06010', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['arts','STEM']::text[], ARRAY['field trips','bowling','tie dye','water play','art studio','science center','laser tag','movies','talent show','camp olympics']::text[], NULL, NULL, NULL, 1, 7, 'A city day camp at Bristol Eastern High School for grades 1 to 3 and 4 to 7, weekdays 9 am to 3 pm for six weeks. Each week has bowling, a water play day and outings or visitors such as a Bristol Blues game, the CT Science Center, laser tag and a movie, with admission fees included.', NULL, NULL, 150, 150, 150, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '37bc348a-fe9d-59b6-a1b5-cd093cb59b85', 'summer-fun-camp-bristol', ST_GeogFromText('SRID=4326;POINT(-72.9407 41.6816)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bristolct.myrec.com/documents/2026_summer_fun_camp_gr_13_weekly_calendar.pdf','https://bristolct.myrec.com/documents/2026_summer_fun_camp_gr_47_weekly_calendar.pdf','https://bristolct.myrec.com/info/default.aspx']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Place', 'University of Hartford', 'https://www.hartford.edu/community/summerplace/', NULL, 'splace@hartford.edu', '860-768-4432', '200 Bloomfield Avenue', 'West Hartford', 'CT', '06117', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['STEM','performing_arts','sports','leadership']::text[], ARRAY['science and technology','culinary arts','theater','recreational sports','art','music','stories','off campus trips']::text[], NULL, NULL, NULL, NULL, 12, 'Day camp on the University of Hartford campus with groups from preschool through high school. Younger children play, make art and hear stories, grades 1 to 9 choose science, cooking, theater and sports, and teens in grades 10 to 12 train as leaders working with younger campers.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '597d5a3d-2efc-5622-becf-2e082fa1b4d5', 'summer-place-west-hartford', ST_GeogFromText('SRID=4326;POINT(-72.7549 41.7666)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hartford.edu/community/summerplace/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Youth Academy Series', 'University of New Haven', 'https://www.newhaven.edu/admissions/pre-college/summer-youth/index.php', 'https://admissions.newhaven.edu/register/?id=5ddc8bfa-a93e-4c2f-b2cb-9b230b3b0739', NULL, '203-932-7000', '300 Boston Post Road', 'West Haven', 'CT', '06516', 'Connecticut', 'specialty', ARRAY['academic','STEM']::text[], ARRAY['arts','leadership']::text[], ARRAY['forensic science','engineering','robotics','filmmaking','interior design','entrepreneurship','health professions','songwriting and music production','marine science','model united nations','genetics']::text[], NULL, NULL, NULL, 6, 12, 'Week long pre college academies on the University of New Haven campus in West Haven, each on one subject such as crime scene investigation, engineering, filmmaking or health professions. Students work with university faculty during the day, and some academies offer an overnight option in a residence hall.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, 'Refunds are granted before June 1, 2026 minus a 25% processing fee; no refunds after June 1, 2026.', NULL, NULL, NULL, NULL, 2026, 'd7d18672-fdf2-5c4b-91c1-7243e9bf0584', 'summer-youth-academy-series-west-haven', ST_GeogFromText('SRID=4326;POINT(-72.9675 41.2721)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.newhaven.edu/admissions/pre-college/summer-youth/academy-programs.php','https://www.newhaven.edu/admissions/pre-college/summer-youth/index.php']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summerscape Day Camp', 'Rocky Hill Parks & Recreation', 'https://rockyhillct.myrec.com/documents/summerscape_day_camp_parent_handbook__updated_22426.pdf', 'https://rockyhillct.myrec.com/info/', NULL, '860-258-2772', 'Rocky Hill High School, 50 Chapin Avenue', 'Rocky Hill', 'CT', '06067', 'Connecticut', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','sports']::text[], ARRAY['swimming','water activities','electives','spirit days','theme weeks','talent show']::text[], NULL, 4, NULL, NULL, 5, 'A town day camp at Rocky Hill High School for children from age 4 (pre-K) through grade 5, open to residents and non-residents, 8:30 am to 4 pm in weekly sessions. Campers have weekly themes and spirit days, grades 1 to 5 swim in the school''s indoor pool, and grades 3 to 5 pick a weekly elective. The camp stays on site.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, NULL, NULL, NULL, 'Grades 1 to 5 swim in the Rocky Hill High School indoor pool with certified lifeguards; pre-K and kindergarten have water activities instead. Life jackets case by case.', NULL, NULL, 2026, 'f0ceb592-35d3-5552-923d-7e011813cc85', 'summerscape-day-camp-rocky-hill', ST_GeogFromText('SRID=4326;POINT(-72.6618 41.6566)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://rockyhillct.myrec.com/documents/summerscape_day_camp_parent_handbook__updated_22426.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Acadia Institute of Oceanography', 'Acadia Institute of Oceanography', 'https://acadiainstitute.com/', 'https://aio.campintouch.com/ui/forms/application/camper/App', 'explore@acadiainstitute.com', '207-669-3561', '9 Lower Dunbar Road', 'Mount Desert', 'ME', '04675', 'Maine', 'specialty', ARRAY['STEM','nature']::text[], ARRAY['academic','outdoor']::text[], ARRAY['saltwater tank','beach exploration','tide pools','salt marshes and bogs','fishing','whale watching','island geology','water testing']::text[], 'coed', 10, 18, 5, 12, 'Overnight marine science camp in Seal Harbor on Mount Desert Island. Students study the ocean through classes, lab work, tide pools, salt marshes and boat trips, in a one week session for ages 10 to 12 and two week sessions for middle and high school students.', NULL, NULL, 1800, 3400, NULL, 'session', NULL, TRUE, TRUE, NULL, 'Full refund before March 1. From March 1 to April 30, refund minus the deposit ($400 Introductory, $600 others). In May, refund minus deposit only if the place is filled. No refunds from June 1.', 'Many students with ADD, ADHD or mild learning disabilities do well, but the program is not staffed for one on one support or more severe needs. Food allergies and many diets can be handled if arranged with the Director at least four weeks ahead.', NULL, NULL, NULL, 2027, '06221faa-3310-5484-aaf8-d9003b41e035', 'acadia-institute-of-oceanography-mount-desert', ST_GeogFromText('SRID=4326;POINT(-68.3304 44.3336)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://acadiainstitute.com/','https://acadiainstitute.com/contact/','https://acadiainstitute.com/faqs/','https://acadiainstitute.com/intermediate-marine-science-camp-program/','https://acadiainstitute.com/introductory-marine-science-camp-program/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Acadia Mountain Guides Adventure Day Camps', 'Acadia Mountain Guides Climbing School', 'https://www.climbacadia.org/', 'https://www.climbacadia.org/booknow', 'climb@acadiamountainguides.com', '207-288-8186', '228 Main Street', 'Bar Harbor', 'ME', '04609', 'Maine', 'specialty', ARRAY['adventure']::text[], ARRAY['outdoor','nature']::text[], ARRAY['rock climbing','rappelling','hiking','swimming','canoeing','rope bridge','knot tying','caving','tide pooling']::text[], NULL, 6, 13, NULL, NULL, 'Week long outdoor adventure day camps in Acadia National Park run by a climbing school. Mountain Monkeys (ages 6 to 9) and Young Explorers (ages 9 to 13) climb, rappel, hike Acadia''s peaks, swim and canoe in small guided groups, with drop off in Bar Harbor, Ellsworth or Bangor.', 'outdoor', NULL, 350, NULL, NULL, 'session', NULL, TRUE, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '69409ab6-af37-59cb-8e86-a882050cf317', 'acadia-mountain-guides-adventure-day-camps-bar-harbor', ST_GeogFromText('SRID=4326;POINT(-68.2638 44.3975)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=228+Main+Street%2C+Bar+Harbor%2C+ME&benchmark=Public_AR_Current&format=json','https://www.climbacadia.org/','https://www.climbacadia.org/locations','https://www.climbacadia.org/rates-financial-aid']::text[], '2026-11-25', '2026-11-25', TRUE),
('Bowdoin Summer Art Camp', 'Bowdoin College', 'https://www.bowdoin.edu/events/art-camp/index.html', NULL, 'artcamp@bowdoin.edu', NULL, '14 South Street', 'Brunswick', 'ME', '04011', 'Maine', 'specialty', ARRAY['arts']::text[], '{}'::text[], ARRAY['painting','collage','cardboard building','shadow puppets','fabric art','weaving','sculpture','woodworking','string art']::text[], NULL, 6, 13, NULL, NULL, 'Week long art day camp at Bowdoin College in Brunswick for ages 6 to 13, grouped 6 to 7, 8 to 10 and 11 to 13. Each day has a morning and an afternoon studio class led by working artists, in media such as collage, painting, cardboard, fabric, puppets, weaving and wood, ending with a Friday art show.', 'both', NULL, 400, NULL, 400, 'week', FALSE, NULL, FALSE, NULL, 'Full refund if Bowdoin cancels or if a family withdraws before camp starts; no partial or prorated refunds and none once camp starts.', NULL, NULL, NULL, NULL, 2026, 'ed4bdf67-071f-5e51-bd30-d2c32cda9271', 'bowdoin-summer-art-camp-brunswick', ST_GeogFromText('SRID=4326;POINT(-69.9651 43.9145)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.bowdoin.edu/events/art-camp/art-camp-summer-handbook-2026.pdf','https://www.bowdoin.edu/events/art-camp/index.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Crescent Cove', 'Camp Crescent Cove', 'https://campcrescentcove.com/dates-tuition/', 'https://campcrescentcove.campintouch.com/ui/forms/application/camper/App', 'info@campcrescentcove.com', '207-770-5540', '198 Raymond Hill Road', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['general']::text[], ARRAY['swimming','sailing','sports','arts','performing_arts','adventure']::text[], ARRAY['canoe and kayak','fishing','sailing','stand up paddleboarding','tubing','wakeboarding','waterskiing','windsurfing','athletics','golf','tennis','arts and crafts','pottery','culinary arts','photography','woodworking','animal care','climbing','trips','horseback riding','dance','music','theater']::text[], 'coed', 7, 16, NULL, NULL, 'Coed overnight camp in Raymond, Maine, for boys and girls ages 7 to 16, with two week and three and a half week sessions. Campers choose from water sports, land sports, arts, performing arts, climbing, riding and trips, and current 10th graders can join the Summit leadership program.', NULL, NULL, 6200, 9300, NULL, 'session', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '9e1d2329-91bf-506b-9352-c8c97973e6f8', 'camp-crescent-cove-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://campcrescentcove.com/dates-tuition/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp NEOFA', 'Northeast Odd Fellows'' Association', 'https://www.campneofa.me/', 'https://www.campneofa.me/apply', NULL, '(207) 589-4133', '213 North Trotting Park Road', 'Montville', 'ME', '04941', 'Maine', 'sleepaway', ARRAY['general','outdoor']::text[], ARRAY['nature','swimming','sports','arts']::text[], ARRAY['swimming','canoeing','kayaking','archery','fishing','arts and crafts','volleyball','field sports','hiking','nature','camp paper','talent show','dances','campfires']::text[], 'coed', 8, 14, NULL, NULL, 'Coed overnight camp on Trues Pond in Montville, run by the Northeast Odd Fellows'' Association for four one week sessions, Sunday noon to Saturday noon. Campers swim, canoe, kayak, fish, try archery, crafts and field sports, with themed evening events; a day camp option is also offered.', 'outdoor', NULL, 300, 450, 450, 'week', NULL, NULL, NULL, NULL, 'A $75 deposit must come with the application; it is transferable but not refundable.', NULL, NULL, NULL, NULL, 2026, 'eb9cbdbc-ec57-5e75-a110-3dff9c6e1b9d', 'camp-neofa-montville', ST_GeogFromText('SRID=4326;POINT(-69.2917 44.4326)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=213+North+Trotting+Park+Road%2C+Montville%2C+ME&benchmark=Public_AR_Current&format=json','https://www.campneofa.me/','https://www.campneofa.me/apply','https://www.campneofa.me/directions','https://www.campneofa.me/s/2026-Camper-Application-2.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Skylemar', NULL, 'https://campskylemar.com/', 'https://campskylemar.com/enroll/', 'info@skylemar.com', '(207) 693-6414', '457 Sebago Road', 'Naples', 'ME', '04055', 'Maine', 'sleepaway', ARRAY['sports']::text[], ARRAY['swimming','sailing','adventure','arts']::text[], ARRAY['swimming','soccer','lacrosse','baseball','golf','tennis','waterskiing','archery','football','sailing','kayaking','canoeing','basketball','hockey','challenge course','outdoor education','trips','color war']::text[], 'boys', 7, 15, NULL, NULL, 'Overnight camp for boys ages 7 to 15 on Trickey Pond in Naples, Maine. Days center on land and water sports with private instruction, plus a ropes course, arts, woodshop and trips.', NULL, NULL, 12850, 18500, NULL, 'session', NULL, TRUE, NULL, NULL, NULL, NULL, 'On Trickey Pond, about three miles long. The camp lists swimming, waterskiing, wakeboarding, tubing, sailing, canoeing, kayaking, paddleboarding, snorkeling and fishing.', NULL, NULL, 2027, '9601bc1c-c7cb-5b99-bd4c-f77f2c50229e', 'camp-skylemar-naples', ST_GeogFromText('SRID=4326;POINT(-70.6393 43.9758)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://campskylemar.com/about-camp/','https://campskylemar.com/about-camp/activities/','https://campskylemar.com/about-camp/enrollment/','https://campskylemar.com/about-camp/facilities/']::text[], '2026-11-25', '2026-11-25', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Camp Somerset for Girls', 'Camp Somerset', 'https://somersetforgirls.com/', 'https://somerset.campintouch.com/ui/forms/application/camper/App', NULL, '617-744-3385', '11 Somerset Lane', 'Smithfield', 'ME', '04978', 'Maine', 'sleepaway', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['swimming','sailing','kayaking','canoeing','fishing','waterskiing','wakeboarding','gymnastics','yoga','martial arts','cycling']::text[], 'girls', NULL, NULL, NULL, NULL, 'Overnight camp for girls on 50 acres along East Pond in Smithfield, in the Belgrade Lakes region. Girls who have finished grades 3 to 9 live in cabins by age, with a large waterfront for sailing, waterskiing and paddling and a gym for gymnastics, in a seven week or three and a half week session.', NULL, NULL, 10800, 17900, NULL, 'session', NULL, NULL, TRUE, NULL, NULL, NULL, '2,000 feet of waterfront on East Pond with swimming, sailing, kayaking, canoeing, fishing and a waterski and wakeboard program.', NULL, NULL, 2027, '04c330ff-79b2-5c47-abfb-e3695830e0ca', 'camp-somerset-for-girls-smithfield', ST_GeogFromText('SRID=4326;POINT(-69.7999 44.6418)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://somersetforgirls.com/about/location-facilities','https://somersetforgirls.com/dates-rates']::text[], '2026-11-25', '2026-11-25', TRUE),
('Chop Point', 'Chop Point, Inc.', 'https://choppointcamp.org/', 'https://choppointcamp.org/enroll/', NULL, '207-443-5860', '420 Chop Point Road', 'Woolwich', 'ME', '04579', 'Maine', 'sleepaway', ARRAY['general']::text[], ARRAY['adventure','sailing','faith']::text[], ARRAY['tennis','basketball','soccer','kayaking','sailing','windsurfing','surfing','hiking','biking','swimming','photography','art','music','adventure trips']::text[], NULL, 12, 18, NULL, NULL, 'Overnight camp for teenagers ages 12 to 18 in Woolwich, Maine, run by a Christian nonprofit since 1967. Campers set their own daily schedule from sports, sailing, windsurfing, kayaking, art and music, choose one to five day trips each session, and leave devices at home.', NULL, 'Christian', 2800, 5000, NULL, 'session', NULL, TRUE, NULL, TRUE, 'A $500 deposit is required and is not refundable; the balance is due two weeks before arrival. No refund for early withdrawal, cancellation or dismissal.', NULL, NULL, NULL, NULL, 2027, '8fb2d144-3d03-5ed9-973a-b19ceeeeec7d', 'chop-point-woolwich', ST_GeogFromText('SRID=4326;POINT(-69.7694 43.9597)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://choppointcamp.org/','https://choppointcamp.org/about/','https://choppointcamp.org/enroll/','https://choppointcamp.org/enroll/financial-aid/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Clipper Day Camp', 'Yarmouth Community Services', 'https://www.yarmouthcommunityservices.org/summer-camps', 'https://yarmouthme.myrec.com/info/default.aspx', NULL, '(207) 846-2406', NULL, 'Yarmouth', 'ME', '04096', 'Maine', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['gym games','arts and crafts','outdoor games','swimming at Greely Pool','field trips']::text[], NULL, 5, 11, 0, 5, 'Town day camp in Yarmouth for kids entering kindergarten to grade 5. Grades K and 1 meet at Rowe School and grades 2 to 5 at Yarmouth Elementary School, with gym and outdoor games, crafts, pool days and weekly field trips.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '7495ee7e-a431-5b5d-b7b2-d89c6bc4934f', 'clipper-day-camp-yarmouth', ST_GeogFromText('SRID=4326;POINT(-70.1565 43.7881)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.yarmouthcommunityservices.org/_files/ugd/6ae268_2aca70b97f7744e0b0ee231d3defb005.pdf','https://www.yarmouthcommunityservices.org/_files/ugd/6ae268_7d4c8bfe04324721af45421a4bf4c87e.pdf','https://www.yarmouthcommunityservices.org/summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('Fernwood Cove', 'Fernwood Cove', 'https://www.fernwoodcove.com/', NULL, 'cove@fernwoodcove.com', '207-583-2381', '350 Island Pond Road', 'Harrison', 'ME', '04040', 'Maine', 'sleepaway', ARRAY['general']::text[], ARRAY['swimming','arts','performing_arts','outdoor','sports']::text[], ARRAY['athletics and fitness','creative arts','outdoor adventure','performing arts','studio arts','waterfront','natural horsemanship and agriculture']::text[], 'girls', NULL, NULL, NULL, NULL, 'Traditional overnight camp for girls on Island Pond in Harrison, Maine, about an hour from Portland. Each girl attends one half summer session and builds her own schedule from more than 60 activities in sports, arts, outdoor adventure, waterfront and horsemanship.', NULL, NULL, 6750, 10400, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, 'Camp sits on Island Pond. Campers take one week of instructional swimming each session until they have finished 7th grade and reached Red Cross swim level 6.', NULL, NULL, 2027, 'f2955cd6-fc51-5d75-b83b-c25c442e94e3', 'fernwood-cove-harrison', ST_GeogFromText('SRID=4326;POINT(-70.6524 44.1027)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.fernwoodcove.com/','https://www.fernwoodcove.com/about/activities/','https://www.fernwoodcove.com/about/dates-and-tuition/','https://www.fernwoodcove.com/about/faqs/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Gander Brook Christian Camp', 'Gander Brook Christian Camp', 'https://ganderbrook.org/summer-camp/', 'https://app.campdoc.com/!/dn/login?r=gander', 'info@ganderbrook.org', '207-998-4369', '27 Ganderbrook Lane', 'Raymond', 'ME', '04071', 'Maine', 'sleepaway', ARRAY['general','faith']::text[], ARRAY['outdoor','sports','swimming']::text[], ARRAY['carpet ball','cookouts','flag football','basketball','four square','ping pong','camping under the stars','paintball','skit nights','softball','soccer','ultimate frisbee','volleyball','drama','arts and crafts','swimming','canoeing','hiking','kayaking','air rifles','archery','bible classes','ropes course','climbing wall','singing','fishing']::text[], 'coed', 8, 18, NULL, NULL, 'Christian overnight camp in the woods of Raymond, Maine, open to children of all backgrounds, with Saturday to Saturday weeks for ages 8 to 18. Days mix sports, swimming, canoeing, climbing and camping out with Bible classes and devotions, and phones stay at home. A weekday day camp for ages 8 to 13 is also offered.', NULL, 'Christian', 550, 850, 550, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '7ed72513-1e8d-5335-b8aa-3df428d9b6b9', 'gander-brook-christian-camp-raymond', ST_GeogFromText('SRID=4326;POINT(-70.4685 43.9176)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ganderbrook.org/activities','https://ganderbrook.org/summer-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Get Out and Go Camp', 'Yarmouth Community Services', 'https://www.yarmouthcommunityservices.org/summer-camps', 'https://yarmouthme.myrec.com/info/default.aspx', NULL, '(207) 846-2406', NULL, 'Yarmouth', 'ME', '04096', 'Maine', 'day', ARRAY['outdoor','adventure']::text[], ARRAY['swimming','nature']::text[], ARRAY['beach trips','lake trips','hiking','canoeing','ropes course','river tubing','water parks','amusement park']::text[], NULL, 11, 14, 6, 8, 'Town trip camp in Yarmouth for kids in grades 6 to 8. Each day, Monday to Thursday, the group leaves from Harrison Middle School for a full day out: beaches, lakes, hikes, a canoe trip, a ropes course and water parks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'fbfeb340-f002-5461-88e1-83d141f13cf0', 'get-out-and-go-camp-yarmouth', ST_GeogFromText('SRID=4326;POINT(-70.1565 43.7881)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.yarmouthcommunityservices.org/_files/ugd/6ae268_038616acbfd3487ba8bb8d78ef325fa9.pdf','https://www.yarmouthcommunityservices.org/_files/ugd/6ae268_dcf1c79baf7c4f82ba8ade1d54bc1417.pdf','https://www.yarmouthcommunityservices.org/summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('Hart-to-Hart Farm Day Camp', 'Hart to Hart Farm and Educational Center', 'https://hart2hartfarm.org/seasonal-farm-camps/', 'https://hart2hartfarm.org/register/', 'hart2hartfarm@gmail.com', '207-437-2441', '16 Duck Pond Lane', 'Albion', 'ME', '04910', 'Maine', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['animal care','barn chores','gardening','crafts','cooking','games','pioneer skills']::text[], NULL, 5, 14, NULL, NULL, 'Farm day camp on a family run organic dairy farm in Albion, Maine. Each week campers care for an adopted animal, do barn chores and farm projects, and follow a theme such as cooking with farm food, 1800s pioneer life or crafts, with a week just for 5 and 6 year olds.', NULL, NULL, 425, NULL, 425, 'week', NULL, NULL, NULL, TRUE, 'Written notice two weeks before the session gets a full refund minus the $50 deposit; no refunds for missed days.', NULL, NULL, NULL, NULL, 2027, '0ae02b25-a3f7-5e9f-8eb0-5565594b2e83', 'hart-to-hart-farm-day-camp-albion', ST_GeogFromText('SRID=4326;POINT(-69.4452 44.5084)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://hart2hartfarm.org/seasonal-farm-camps/','https://hart2hartfarm.org/wp-content/uploads/2026/10/2027-ColorCampbrochure.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Kit Camp at Camp Kerith', 'Berea', 'https://www.kerith.camp/daycamp', 'https://kerith.campbrainregistration.com/', 'office@berea.org', '603-744-6344', '67 Cedarbrook Way', 'Lyman', 'ME', '04002', 'Maine', 'day', ARRAY['general','faith']::text[], ARRAY['outdoor','swimming']::text[], ARRAY['arts and crafts','field games','tubing','swimming','target sports','canoeing','kayaking','riflery','archery','campfire worship']::text[], NULL, 5, 15, NULL, NULL, 'Christian summer day camp in Lyman, Maine, near I 95, for ages 5 to 15, Monday to Friday 7:45 am to 5:15 pm. Campers swim, canoe, kayak, go tubing, try archery and riflery, play field games and do crafts, with daily Bible teaching and worship.', NULL, 'Christian', 300, 315, 315, 'week', TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, 'aea6caf4-774d-54e0-b7ed-d2ed946f7031', 'kit-camp-at-camp-kerith-lyman', ST_GeogFromText('SRID=4326;POINT(-70.648 43.4997)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.kerith.camp/daycamp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Mariners Adventure Camp', 'Maine Maritime Museum', 'https://www.mainemaritimemuseum.org/mariners-adventure', 'https://maritimeme.campbrainregistration.com/?returnUrl=%252FLanding', 'camp@maritimeme.org', '(207) 443-1316', '243 Washington St', 'Bath', 'ME', '04530', 'Maine', 'day', ARRAY['academic','sailing']::text[], ARRAY['arts','leadership']::text[], ARRAY['carpentry','blacksmithing','sailmaking','navigation','marlinspike seamanship','schooner sailing trip']::text[], NULL, 11, 14, 6, 8, 'A week-long day camp at the Maine Maritime Museum in Bath for students entering grades 6 to 8. Campers learn traditional ship trades such as carpentry, blacksmithing, sailmaking and navigation, and take a trip to Bailey Island to sail a schooner.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '1a602842-fea1-5d1d-af38-720ef09b3e8e', 'mariners-adventure-camp-bath', ST_GeogFromText('SRID=4326;POINT(-69.8472 43.9325)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.mainemaritimemuseum.org/mariners-adventure']::text[], '2026-11-25', '2026-11-25', TRUE),
('Nature Day Camp', 'Harpswell Heritage Land Trust', 'https://hhltmaine.org/nature-day-camp/', 'https://portal.campnetwork.com/Register/Register.php?camp_id=399045', 'info@hhltmaine.org', '207-721-1121', NULL, 'Harpswell', 'ME', '04079', 'Maine', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['tide pools','salt marsh exploration','hiking','nature crafts','science discovery','outdoor games']::text[], NULL, 6, 12, NULL, NULL, 'Outdoor nature day camp run by the Harpswell Heritage Land Trust, using its preserves as the classroom. Two age groups, 6 to 8 and 9 to 12, spend weekly themed sessions exploring tide pools, salt marshes, shores and forests through games, crafts and hands on science.', 'outdoor', NULL, 275, 300, NULL, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '0e8aef17-8378-527c-8bf9-e289d013cb91', 'nature-day-camp-harpswell', ST_GeogFromText('SRID=4326;POINT(-69.9714 43.7337)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://hhltmaine.org/nature-day-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Nature Explorer Camp with KELT & Brightfield', 'Kennebec Estuary Land Trust', 'https://www.kennebecestuary.org/upcoming-events/nature-day-camp-2026', 'https://brightfieldschool.org/summer-program/', NULL, '207-442-8400', '340 Oak Grove Avenue', 'Bath', 'ME', '04530', 'Maine', 'day', ARRAY['nature']::text[], ARRAY['outdoor','adventure']::text[], ARRAY['hiking','paddleboarding','clamming','cooking chowder over a fire','beach day','nature art']::text[], NULL, 6, 10, NULL, NULL, 'Nature day camp run by the Kennebec Estuary Land Trust with Brightfield School educators, based at Brightfield School in Bath. Campers ages 6 to 10 ride the school van to hike, paddleboard, dig clams, explore marshes and make nature art, ending the week with a beach day at Fort Popham.', 'outdoor', NULL, 325, NULL, 325, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '19dccf41-4800-5df9-88e6-2908c2941a8c', 'nature-explorer-camp-with-kelt-and-brightfield-bath', ST_GeogFromText('SRID=4326;POINT(-69.8472 43.9325)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.kennebecestuary.org/summer-camp','https://www.kennebecestuary.org/upcoming-events/nature-day-camp-2026']::text[], '2026-11-25', '2026-11-25', TRUE),
('North Yarmouth Academy Summer Programs', 'North Yarmouth Academy', 'https://www.nya.org/community-life/summer-programs', 'https://campscui.active.com/orgs/NorthYarmouthAcademy?orglink=camps-registration', NULL, '207-846-9051', '148 Main St.', 'Yarmouth', 'ME', '04096', 'Maine', 'day', ARRAY['general']::text[], ARRAY['arts','sports','STEM','nature','performing_arts']::text[], ARRAY['toddler camp','preschool camp','primary arts','general day camp','lego','magic','circus arts','STEAM','sports and games','state parks adventure','tennis','soccer','ice hockey','dance','improv and theater','sewing','farm camp','robotics','ceramics','biking','hiking','sailing','counselor in training']::text[], NULL, 2, 16, NULL, NULL, 'Weekly day camps on the North Yarmouth Academy campus in Yarmouth, Maine, for ages 2 to 16. Each week offers many separate programs, from toddler camps and general day camp to sports, arts, Lego, robotics, circus arts, farm and outdoor adventure camps, several run by partner groups.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The $50 deposit per session is never refunded. Full refund less deposit for cancellations 21 or more days before the start, 50 percent less deposit after that, and none within seven days. Partner camps are not refunded after June 1.', 'Campers of differing abilities are welcome, but staff ratios do not allow constant one on one support; call the Director of Summer Programs to plan. Toddler campers ages 2 to 3 need not be potty trained.', NULL, NULL, NULL, 2026, '8b1a2105-333b-5afb-9827-dfd3bf5cc54a', 'north-yarmouth-academy-summer-programs-yarmouth', ST_GeogFromText('SRID=4326;POINT(-70.1565 43.7881)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.nya.org/community-life/summer-programs','https://www.nya.org/userfiles/northyarmouthacademymvc/00-document/Week%20By%20Week%20Camp%20List%20June%203%202026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Penobscot Marine Museum Kids Summer Camp', 'Penobscot Marine Museum', 'https://penobscotmarinemuseum.org/kids-camps/', NULL, 'jganskop@pmm-maine.org', '207-548-2529', '40 E Main Street', 'Searsport', 'ME', '04974', 'Maine', 'day', ARRAY['general']::text[], ARRAY['arts','academic']::text[], ARRAY['crafts','games','exhibit visits','music','sailing demonstrations']::text[], NULL, 5, 10, NULL, NULL, 'Week long themed day camp at the Penobscot Marine Museum in Searsport for ages 5 to 10. Days mix crafts, games, music and exhibit visits on sea and coastal themes, and campers help with the museum''s daily Set Sail demonstrations.', NULL, NULL, 220, NULL, 220, 'week', TRUE, NULL, NULL, TRUE, 'Refunds until 9 pm the day before the program, minus a 10 percent fee; none after that.', NULL, NULL, NULL, NULL, 2027, 'f72bfac0-c61a-55b2-9d45-4496b3796a5b', 'penobscot-marine-museum-kids-summer-camp-searsport', ST_GeogFromText('SRID=4326;POINT(-68.9287 44.4709)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://penobscotmarinemuseum.org/kids-camps/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Daze Camp', 'University of Maine at Farmington Fitness & Recreation Center', 'https://farmington.edu/student-life/athletics-recreation/youth-camps-programs/', 'https://farmington.edu/app/uploads/2026/05/Copy-of-2026-SDC-Registration-Form.docx.pdf', 'umffrc@maine.edu', '207-778-7495', '152 Quebec Street', 'Farmington', 'ME', '04938', 'Maine', 'day', ARRAY['general']::text[], ARRAY['outdoor','STEM']::text[], ARRAY['themed games','crafts','STEM challenges','field trips','outdoor games']::text[], NULL, 6, 13, 1, 7, 'Weekly day camp at the University of Maine at Farmington for children entering grades 1 to 7. Each week has a history or science theme, such as dinosaurs, knights or inventors, with games, building projects and trips around Western Maine.', NULL, NULL, 235, NULL, 235, 'week', TRUE, NULL, NULL, NULL, 'No refunds once a session has started.', NULL, NULL, NULL, NULL, 2026, 'bcce5def-4468-5475-9cfa-343661604a95', 'summer-daze-camp-farmington', ST_GeogFromText('SRID=4326;POINT(-70.1415 44.6769)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://farmington.edu/app/uploads/2026/05/Copy-of-2026-SDC-Registration-Form.docx.pdf','https://farmington.edu/student-life/athletics-recreation/youth-camps-programs/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer RAD Camp', 'UMaine Campus Recreation and the Town of Orono', 'https://umaine.edu/campusrecreation/summer-camps/', 'https://secure.rec1.com/ME/orono-me/catalog', 'erin.wool@maine.edu', NULL, NULL, 'Orono', 'ME', '04469', 'Maine', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming','nature']::text[], ARRAY['swimming','rock climbing','sports','arts and crafts','canoeing','field games','library time','field trips']::text[], NULL, 5, 11, 0, 5, 'Weekly day camp for kids in kindergarten to grade 5, based on the University of Maine campus in Orono. Each week has a theme, with swimming, climbing, sports, crafts, canoeing and trips around Orono and Bangor.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '54a83b7e-08cc-5eb2-a174-7b6a773d6389', 'summer-rad-camp-orono', ST_GeogFromText('SRID=4326;POINT(-68.7386 44.8817)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://umaine.edu/campusrecreation/summer-camps/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Farm Camp', 'Treworgy Family Orchards', 'https://treworgyorchards.com/farm-camp', NULL, NULL, NULL, '3876 Union Street', 'Levant', 'ME', '04456', 'Maine', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['animal care','horseback riding','goat milking','barn chores','wagon rides','frog catching','water games','cheese making','jam making','soap making','farm journal']::text[], NULL, 6, 12, NULL, NULL, 'Week long farm day camp at Treworgy Family Orchards in Levant for ages 6 to 12. Campers care for goats, ride horses, help with barn chores, catch frogs and make cheese, jam and soap, ending each week with a Friday farm parade for families.', 'outdoor', NULL, 545, NULL, 545, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'dcdd6a15-584f-5e56-96aa-c7f89e008d60', 'treworgy-farm-camp-levant', ST_GeogFromText('SRID=4326;POINT(-68.9967 44.8768)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://treworgyorchards.com/farm-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Zillman Art Museum Summer Art Camp', 'Zillman Art Museum, University of Maine', 'https://zam.umaine.edu/education/art-camp/summer-art-camp/', NULL, 'um.zillmanmuseum@maine.edu', '207-581-3300', '40 Harlow Street', 'Bangor', 'ME', '04401', 'Maine', 'specialty', ARRAY['arts']::text[], '{}'::text[], ARRAY['printmaking','drawing','painting','textiles','sculpture','crafts','gallery visits']::text[], NULL, NULL, NULL, 1, 6, 'Small half day art camp at the Zillman Art Museum in downtown Bangor, run by the museum educator. Children entering grades 1 to 6 look at and talk about the current exhibitions and make prints, drawings, paintings, textiles and sculpture, with a family show on Friday.', NULL, NULL, 200, NULL, 200, 'week', FALSE, NULL, NULL, NULL, 'Tuition is not refundable within four weeks of the session start.', NULL, NULL, NULL, NULL, 2026, 'd6a9dee5-a24d-52c7-9e88-a18ad161486a', 'zillman-art-museum-summer-art-camp-bangor', ST_GeogFromText('SRID=4326;POINT(-68.7888 44.8296)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://zam.umaine.edu/education/art-camp/summer-art-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Action Adventures Day Camp', 'Berkshire South Regional Community Center', 'https://berkshiresouth.org/aadc/', NULL, NULL, NULL, '15 Crissey Road', 'Great Barrington', 'MA', '01230', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','STEM','sports','nature']::text[], ARRAY['arts and crafts','capture the flag','recreational swim','STEM activities','hiking','sports','music','talent show','field trips']::text[], NULL, 5, 14, 0, 8, 'Nine week day camp at the Berkshire South community center in Great Barrington for ages 5 to 14. Campers use the pool, fields, playgrounds and trails for swimming, sports, crafts, STEM and music, with a new theme each week and a talent show.', 'both', NULL, 360, 450, 450, 'week', NULL, NULL, FALSE, TRUE, 'Fully refundable by May 1 except the $50 registration fee; from May 1 to June 30 the deposit and fee are kept; no refunds after July 1 except for serious illness or injury.', NULL, NULL, NULL, NULL, 2026, 'dcb1120c-c795-5d19-90fb-3923c92aa330', 'action-adventures-day-camp-great-barrington', ST_GeogFromText('SRID=4326;POINT(-73.3332 42.2217)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://berkshiresouth.org/aadc/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Berkshire Trails Camp', 'Berkshire Trails Camp', 'https://berkshiretrailscamp.com/', NULL, 'info@berkshiretrailscamp.com', '(413) 644-0077', '25 Deerwood Park Rd', 'Great Barrington', 'MA', '01230', 'Central & Western Massachusetts', 'sleepaway', ARRAY['general']::text[], ARRAY['sports','adventure','arts','performing_arts','swimming']::text[], ARRAY['rock climbing','horseback riding','circus','skate park','waterskiing','wakeboarding','sailing','kayaking','swimming','ceramics','culinary arts','videography','basketball','soccer','tennis','golf','musical theater','rock band','dance']::text[], 'coed', 7, 17, 2, 11, 'Coed overnight camp in Great Barrington, founded in 1968 as Kutsher''s Sports Academy, with sessions of two to seven weeks. Campers pick five classes a week from sports, waterfront, adventure, arts and performing arts.', 'both', NULL, 4995, 14800, NULL, 'session', NULL, TRUE, TRUE, NULL, 'All fees, deposit included, are fully refundable through January 1; no refunds after January 1.', NULL, NULL, NULL, NULL, 2027, '34fd3483-f83a-5965-ab1f-fd7dd5b4d1e7', 'berkshire-trails-camp-great-barrington', ST_GeogFromText('SRID=4326;POINT(-73.3332 42.2217)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://berkshiretrailscamp.com/','https://berkshiretrailscamp.com/current-families/transportation','https://berkshiretrailscamp.com/dates-rates','https://berkshiretrailscamp.com/future-families/activities','https://berkshiretrailscamp.com/future-families/food-nutrition']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Emerson', 'CampGroup', 'https://www.campemerson.com/', 'https://www.campemerson.com/enroll/', 'hello@campemerson.com', '413-655-8123', '212 Longview Avenue', 'Hinsdale', 'MA', '01235', 'Central & Western Massachusetts', 'sleepaway', ARRAY['general','sports','arts']::text[], ARRAY['performing_arts','swimming','adventure','STEM']::text[], ARRAY['waterskiing','wakeboarding','sailing','paddle sports','swim instruction','acting','dance','rock band','theater','drawing and painting','pottery','photography','basketball','gymnastics','soccer','tennis','archery','climbing tower','hiking','rocketry','engineering','woodworking','cooking']::text[], 'coed', 7, 15, NULL, NULL, 'Coed overnight camp on 170 acres beside the Appalachian Trail in Hinsdale, where campers pick eight electives each session from athletics, arts, watersports on two lakes, climbing and a science and making program. Sessions are two weeks, with a one-week option at the end of summer.', 'both', NULL, 2600, 16100, 2600, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, TRUE, 'https://www.campemerson.com/about-us/dates-fees-faqs/', 2027, '44819c60-aa03-503d-b254-dae51eecfdc9', 'camp-emerson-hinsdale', ST_GeogFromText('SRID=4326;POINT(-73.1128 42.4358)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.campemerson.com/about-us/','https://www.campemerson.com/about-us/activities/','https://www.campemerson.com/about-us/dates-fees-faqs/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Hamp', 'Northampton Parks & Recreation Department', 'https://northamptonma.gov/903/Camp-Hamp', 'https://www.northamptonma.gov/1867/Register-For-a-Program-or-Pass', 'recreation@northamptonma.gov', '413-587-1040', NULL, 'Northampton', 'MA', '01062', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['outdoor','sports','arts','swimming']::text[], ARRAY['hiking','cooperative games','sports','arts and crafts','swimming','weekly bus trips','special events']::text[], NULL, NULL, NULL, 5, 6, 'A city run day camp for children entering grades 5 and 6, based at Look Park in Florence, Northampton. Campers do outdoor games, sports and crafts, swim most days at the JFK Middle School pool or a local beach, and go on two bus trips each week. Weekly sessions, 8:30 am to 4:30 pm.', NULL, NULL, 205, 245, 245, 'week', TRUE, NULL, FALSE, TRUE, 'A $25 deposit per session is non-refundable. Refund requests must be made in writing by May 29, 2026; no refunds after that date, and a $10 processing fee applies.', NULL, 'Campers swim at the Aquatic and Family Center at JFK Middle School and at local beaches such as Musante Beach in Leeds.', NULL, NULL, 2026, '50e26396-d295-5d74-ba82-73fd39e08776', 'camp-hamp-northampton', ST_GeogFromText('SRID=4326;POINT(-72.6412 42.3251)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://northamptonma.gov/903/Camp-Hamp','https://northamptonma.gov/DocumentCenter/View/36139']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp KidZone', 'Northampton Parks & Recreation Department', 'https://northamptonma.gov/904/Camp-Kidzone', 'https://www.northamptonma.gov/1867/Register-For-a-Program-or-Pass', 'recreation@northamptonma.gov', '413-587-1040', NULL, 'Northampton', 'MA', '01062', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['sports','arts and crafts','cooperative games','swimming','weekly field trip','Pines Theater shows']::text[], NULL, NULL, NULL, 1, 4, 'A city run day camp for children entering grades 1 to 4 at Look Memorial Park in Florence, Northampton. Days mix sports, crafts and games around a weekly theme, with swimming at the JFK Middle School pool or Musante Beach, a weekly field trip and children''s shows at the park''s Pines Theater. Weekly sessions, 8:30 am to 4:30 pm.', NULL, NULL, 195, 235, 235, 'week', TRUE, NULL, FALSE, TRUE, 'A $25 deposit per session is non-refundable. Refund requests must be made in writing by May 29, 2026; no refunds after that date, and a $10 processing fee applies.', NULL, 'Campers swim Monday, Tuesday and Thursday at the Aquatic and Family Center at JFK Middle School after a swim check by a lifeguard, and Friday afternoons at Musante Beach in Leeds.', NULL, NULL, 2026, 'da2223a2-25af-557f-91ed-a7c607449fa9', 'camp-kidzone-northampton', ST_GeogFromText('SRID=4326;POINT(-72.6412 42.3251)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://northamptonma.gov/904/Camp-Kidzone','https://northamptonma.gov/DocumentCenter/View/36140']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Kinderland', 'Camp Kinderland', 'https://www.campkinderland.org/', NULL, NULL, '413-258-4463', '1543 Colebrook River Rd.', 'Tolland', 'MA', '01034', 'Central & Western Massachusetts', 'sleepaway', ARRAY['general','arts']::text[], ARRAY['performing_arts','sports','swimming','nature']::text[], ARRAY['swim instruction','canoeing','kayaking','soccer','basketball','softball','ultimate frisbee','arts and crafts','pottery','folk dance','singing','drama','hiking','overnight trips']::text[], 'coed', 9, 16, NULL, NULL, 'Overnight camp in Tolland with progressive, secular Jewish roots, for campers 9 to 14 plus counselors in training aged 15 and 16. Groups rotate through swimming, sports, arts and crafts, pottery, folk dance, singing, drama and nature, with a social justice theme woven into camp traditions.', 'both', NULL, 3087, 9230, NULL, 'session', NULL, TRUE, TRUE, TRUE, NULL, NULL, 'Campers swim twice a day on a private lake: instructional swim in the morning and free swim in the afternoon. Beginners stay in a shallow area enclosed by the dock and test up to intermediate and deep water. At least three Red Cross certified lifeguards are on duty, and canoes, kayaks and pedal boats are available under supervision.', NULL, NULL, 2027, '96d0ef0e-5461-536d-ae01-56bee7ccc2ac', 'camp-kinderland-tolland', ST_GeogFromText('SRID=4326;POINT(-73.0346 42.1021)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.campkinderland.org/','https://www.campkinderland.org/faqs','https://www.campkinderland.org/program','https://www.campkinderland.org/sessions']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Lenox', 'Camp Lenox', 'https://camplenox.com/', NULL, 'info@camplenox.com', '413-243-2223', '2042 N Main Rd', 'Otis', 'MA', '01253', 'Central & Western Massachusetts', 'sleepaway', ARRAY['sports']::text[], ARRAY['swimming','adventure','arts']::text[], ARRAY['basketball','waterskiing','tennis','baseball','soccer','gymnastics','kickball','intramural leagues','intercamp tournaments','adventure','creative arts','waterfront']::text[], 'coed', 7, 16, NULL, NULL, 'Coed overnight sports camp on 180 acres above Shaw Pond in Otis. Campers rotate through individual and team sports, waterfront, adventure and creative arts, choose weekly instructional clinics, and play in intramural and intercamp leagues; boys and girls follow separate daytime programs.', 'both', NULL, 6050, 16700, NULL, 'session', NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, TRUE, 'https://camplenox.com/about-camp-lenox', 2027, '3dd37f75-de9a-5a1a-bda6-f0e904d69044', 'camp-lenox-otis', ST_GeogFromText('SRID=4326;POINT(-73.085 42.2043)'), FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://camplenox.com/','https://camplenox.com/about-camp-lenox','https://camplenox.com/dates-and-rates','https://camplenox.com/the-lenox-program-and-activities']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Lewis Perkins Day Camp', 'Girl Scouts of Central & Western Massachusetts', 'https://www.gscwm.org/en/members/for-girl-scouts/camp-and-outdoors/summer-camp/day-camp/clp.html', 'http://app.campdoc.com/register/gscentralwesternmass', 'CLPDirector@gscwm.org', '413-387-3413', '9 Camp Perkins Rd', 'South Hadley', 'MA', '01075', 'Central & Western Massachusetts', 'day', ARRAY['outdoor']::text[], ARRAY['nature','swimming']::text[], ARRAY['team building games','nature art','gaga','archery','swimming','campfire building','hiking','outdoor cooking','crafts','songs']::text[], 'girls', NULL, NULL, 1, NULL, 'Girl Scout day camp in South Hadley open to all girls, with fields, woods and trails. Campers play team games, make nature art, shoot archery, swim in an in ground pool and build campfires, around a weekly theme.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 'Cancel in writing four weeks or more before the session for a refund minus the $75 deposit; no refunds within four weeks or for missed days, with partial or full refunds possible for documented medical emergencies.', NULL, 'Campers swim in an in ground pool, with a modified Christian''s Law swim test; non swimmers wear life jackets in water over two feet deep.', TRUE, 'https://www.gscwm.org/en/members/for-girl-scouts/camp-and-outdoors/summer-camp/day-camp/clp.html', 2026, '5d8c6612-c583-5b1d-a84c-31c22d5c56c0', 'camp-lewis-perkins-day-camp-south-hadley', ST_GeogFromText('SRID=4326;POINT(-72.5802 42.2565)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=9+Camp+Perkins+Rd%2C+South+Hadley%2C+MA&benchmark=Public_AR_Current&format=json','https://www.gscwm.org/content/dam/gscwm-redesign/documents/Camp/2026/2026%20Day%20Camp%20Family%20Handbook%20web.pdf','https://www.gscwm.org/en/members/for-girl-scouts/camp-and-outdoors/summer-camp.html','https://www.gscwm.org/en/members/for-girl-scouts/camp-and-outdoors/summer-camp/day-camp/clp.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Romaca', 'Camp Romaca', 'https://www.romaca.com/', NULL, 'office@romaca.com', '413-655-2715', 'Longview Avenue', 'Hinsdale', 'MA', '01235', 'Central & Western Massachusetts', 'sleepaway', ARRAY['general','sports','arts']::text[], ARRAY['swimming','performing_arts','adventure']::text[], ARRAY['watersports','land sports','fitness','gymnastics','creative and performing arts','horseback riding','outdoor adventure','special events']::text[], 'girls', 6, 16, NULL, NULL, 'All girls overnight camp in Hinsdale, in the Berkshires, running a single seven week season. Campers split their days between sports, gymnastics, arts, horseback riding, adventure and the Plunkett Lake waterfront, with younger girls on a set schedule and older girls choosing their own.', 'both', NULL, 17875, 17875, NULL, 'session', NULL, NULL, TRUE, NULL, 'All tuition and fees are non-refundable after September 15. Tuition and program cancellation insurance is offered through the application.', NULL, 'The waterfront is on Plunkett Lake, with two shallow areas, deep water for advanced instruction, racing lanes, a water slide and a Wibit. Campers have Red Cross swim instruction and an afternoon free swim. Water skiing, kneeboarding, wakeboarding, sailing, canoeing and paddleboarding are offered. Lifeguards and Water Safety Instructors run a double check buddy system.', NULL, NULL, 2027, '879b1f76-a129-57fc-8fac-fb065306b415', 'camp-romaca-hinsdale', ST_GeogFromText('SRID=4326;POINT(-73.1128 42.4358)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.romaca.com/','https://www.romaca.com/all-about-camp','https://www.romaca.com/all-about-camp/waterfront','https://www.romaca.com/contact-us','https://www.romaca.com/dates-rates-application','https://www.romaca.com/visit-camp/driving-directions']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Wind-in-the-Pines', 'YWCA Central Massachusetts', 'https://ywcacm.org/child-care/summer-camp/', NULL, NULL, '508-767-2505', '1 Wind in the Pines Way (89 Parker Street)', 'Leicester', 'MA', '01524', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','nature','arts','outdoor']::text[], ARRAY['swim lessons','recreational swim','boating','arts and crafts','games','sports','literacy','nature trails','gaga ball','STEM']::text[], NULL, 6, 13, NULL, NULL, 'YWCA day camp on Stiles Reservoir in Leicester for ages 6 to 13, with a beach, boathouse and nature trails. Every week has a theme and includes swim lessons, free swim, boating for campers 8 and up, crafts, sports and reading time; a bus runs from the YWCA in Worcester.', 'outdoor', NULL, 250, NULL, 250, 'week', TRUE, TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '86563406-81d4-5635-93c2-26bf02e7eb73', 'camp-wind-in-the-pines-leicester', ST_GeogFromText('SRID=4326;POINT(-71.9123 42.2384)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ywcacm.org/child-care/summer-camp/','https://ywcacm.org/wp-content/uploads/2026/02/2026-Summer-Camp-Parent-Information-and-Handbook.pdf','https://ywcacm.org/wp-content/uploads/2026/02/2026-camp-brochure-1.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Leominster Recreation Summer Programs (Sunshine Bunch, Adventure Squad, Little Flamingos)', 'Leominster Recreation Department', 'https://leominsterma.myrec.com/forms/5996_2026_summer_brochure.pdf', 'https://leominsterma.myrec.com/info/default.aspx', 'recdept@leominster-ma.gov', '978-534-7529', 'Samoset School, 100 DeCicco Drive', 'Leominster', 'MA', '01453', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['sports','arts','outdoor']::text[], ARRAY['sports','games','building challenges','arts and crafts','team building','nature activities','water play','visiting entertainers']::text[], NULL, 4, 12, NULL, NULL, 'Leominster''s town summer programs at Samoset School: Sunshine Bunch for ages 6 to 9 and Adventure Squad for ages 10 to 12 run full days with sports, games, building challenges and crafts, and Little Flamingos is a morning program for ages 4 and 5.', 'both', NULL, 120, 160, 160, 'week', NULL, NULL, FALSE, TRUE, 'Registrations are not refundable unless the department cancels the program; a $10 processing fee applies to any refund.', NULL, NULL, NULL, NULL, 2026, '8c66b5a5-c31e-51bd-bab7-ed7c9820679d', 'leominster-recreation-summer-programs-leominster', ST_GeogFromText('SRID=4326;POINT(-71.7706 42.5209)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=100+DeCicco+Drive%2C+Leominster%2C+MA&benchmark=Public_AR_Current&format=json','https://leominsterma.myrec.com/forms/5996_2026_summer_brochure.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('OPEE Summer Adventures', 'Chicopee Parks Department', 'https://chicopeema.myrec.com/documents/parent_manual_2026.pdf', NULL, NULL, '413-594-3481', 'Stefanik Elementary School, 720 Meadow St.', 'Chicopee', 'MA', '01020', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['sports','games','arts and crafts','swimming','water slide','field trips','bookmobile','end of summer show']::text[], NULL, 5, 13, NULL, NULL, 'Chicopee''s summer day program at Stefanik Elementary School for ages 5 to 13. Weekly themes, sports, games and crafts, swimming three days a week at Ray Ashe pool, a field trip every week, and skits for families on the last day.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, TRUE, NULL, 'Refunds from June 6 to 26, 2026 carry a 25% fee per session; after June 5 a full refund needs medical documentation. No refunds once the program starts on June 29.', NULL, 'Recreational swimming Monday, Wednesday and Friday at Ray Ashe pool, or indoors at a local high school in bad weather, with certified lifeguards.', NULL, NULL, 2026, 'f5c70e69-eff1-5a43-8fe1-841f9d9afde9', 'opee-summer-adventures-chicopee', ST_GeogFromText('SRID=4326;POINT(-72.5702 42.1776)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://chicopeema.myrec.com/documents/parent_manual_2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Safety Village', 'Northampton Parks & Recreation Department', 'https://northamptonma.gov/905/Safety-Village', 'https://www.northamptonma.gov/1867/Register-For-a-Program-or-Pass', 'recreation@northamptonma.gov', '413-587-1040', '255 North Maple St.', 'Northampton', 'MA', '01062', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['outdoor']::text[], ARRAY['safety lessons','guest speakers','bike riding','crafts','games','singing']::text[], NULL, 4, 6, NULL, NULL, 'A half day city camp for children ages 4 to 6 that teaches everyday safety, held at Arcanum Field in Florence, Northampton. Each day has a topic such as fire, traffic, water or animal safety, a visiting speaker from the police, fire department or others, and bike riding on the streets of a small model village. Two week sessions, 8:30 am to noon.', NULL, NULL, 210, 230, NULL, 'session', NULL, NULL, FALSE, TRUE, 'A $25 deposit per session is non-refundable. Refund requests must be made in writing by May 29, 2026; no refunds after that date, and a $10 processing fee applies.', 'Children must be toilet trained.', NULL, NULL, NULL, 2026, '5e47a741-738c-55e0-8362-0265c723bece', 'safety-village-northampton', ST_GeogFromText('SRID=4326;POINT(-72.6412 42.3251)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://northamptonma.gov/905/Safety-Village','https://northamptonma.gov/DocumentCenter/View/36141']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer on the Farm', 'Hancock Shaker Village', 'https://hancockshakervillage.org/farm/summeronthefarm/', 'https://1427.blackbaudhosting.com/1427/Summer-on-the-Farm-Session-1-29Jun2026', 'cdickinson@hancockshakervillage.org', NULL, '1843 West Housatonic St.', 'Pittsfield', 'MA', '01202', 'Central & Western Massachusetts', 'day', ARRAY['nature']::text[], ARRAY['arts','outdoor']::text[], ARRAY['farm animal care','gardening','crafts','fiber arts','woodworking','cooking','hiking','games','history']::text[], NULL, 6, 14, NULL, NULL, 'Week long farm camp at Hancock Shaker Village, a living history museum in Pittsfield. Campers help the farmers with animals and gardens, craft with fiber, wood and metal, cook Shaker recipes, hike the forest trail and explore twenty historic buildings.', 'both', NULL, 350, NULL, 350, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'c8800b8f-69c5-5130-b44f-d0aa2d11e275', 'summer-on-the-farm-hancock-shaker-village-pittsfield', ST_GeogFromText('SRID=4326;POINT(-73.2607 42.4518)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://hancockshakervillage.org/farm/summeronthefarm/']::text[], '2026-11-25', '2026-11-25', TRUE),
('UMass Discovery Camp', 'UMass Amherst Department of Recreation & Wellbeing (Lifelong at UMass)', 'https://www.umass.edu/lifelong/youth/recwell', 'https://recwell.umass.edu/program/GetProgramDetails?courseId=741993e8-646b-4058-83f8-a69e4236a6da', NULL, '413-687-7886', '161 Commonwealth Ave', 'Amherst', 'MA', '01002', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['STEM','arts','nature','sports']::text[], ARRAY['science challenges','art challenges','nature quests','athletics','team building','campus field trips','lunch in dining commons']::text[], NULL, 7, 13, NULL, NULL, 'Week long day camp for ages 7 to 13 run by UMass Amherst Recreation and Wellbeing, with small groups of up to 10. Campers rotate through science, art, nature and sports activities, go on campus field trips and eat lunch in the UMass dining halls.', NULL, NULL, 350, NULL, 350, 'session', TRUE, NULL, TRUE, NULL, 'Cancellations more than 30 days before camp incur a $35 fee; no refunds within 30 days of the start.', NULL, NULL, NULL, NULL, 2026, 'acce1d9d-8e4d-5a8f-b9b6-f958538e56c8', 'umass-discovery-camp-amherst', ST_GeogFromText('SRID=4326;POINT(-72.5199 42.3732)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.umass.edu/lifelong/youth/recwell']::text[], '2026-11-25', '2026-11-25', TRUE),
('Wachusett Meadow Nature Camp', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow/camp', 'https://www.massaudubon.org/programs-events/nature-camps/registration-instructions', NULL, '978-464-1332', '113 Goodnow Road', 'Princeton', 'MA', '01541', 'Central & Western Massachusetts', 'day', ARRAY['nature']::text[], ARRAY['outdoor','leadership']::text[], ARRAY['hiking','ponding','canoeing','nature crafts','nature games','wildlife observation','shelter building','nature photography','nature journaling']::text[], NULL, 3, 17, NULL, NULL, 'Mass Audubon nature day camp at Wachusett Meadow Wildlife Sanctuary in Princeton. Campers hike the trails, explore ponds, fields and forests, canoe Wildlife Pond and make crafts, in groups by age from a half day preschool camp up to week long specialty camps and a Counselor in Training program for teens.', NULL, NULL, 42, 525, NULL, 'session', TRUE, NULL, FALSE, TRUE, NULL, NULL, NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow/camp/about-camp', 2026, 'b9125ea2-2e6d-54f7-b1c7-034a4cab6aa3', 'wachusett-meadow-nature-camp-princeton', ST_GeogFromText('SRID=4326;POINT(-71.8775 42.4541)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow/camp/about-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/wachusett-meadow/camp/programs-pricing']::text[], '2026-11-25', '2026-11-25', TRUE),
('YMCA Camp Boroughs', 'YMCA of Central Massachusetts (Boroughs Family Branch YMCA)', 'https://www.ymcaofcm.org/camp-boroughs/', 'https://operations.daxko.com/Online/5104/ProgramsV2/Search.mvc?keywords=&program_id=&expanded=categories%2Clocations&coming_soon=False&category_ids=CAT499&all_categories=false&location_ids=B371&all_locations=false&date_ranges%5B0%5D.start=&date_ranges%5B0%5D.end=&birth_dates=', 'lharding@ymcaofcm.org', NULL, '4 Valente Drive', 'Westborough', 'MA', '01581', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','outdoor','leadership']::text[], ARRAY['swimming','sports','arts and crafts','team games','archery','stem','water games','nature adventure zone','field trips']::text[], NULL, 3, 14, NULL, NULL, 'Outdoor YMCA day camp in Westborough for ages 3 to 12, with leadership and counselor in training programs for older kids. Campers swim, play sports, do crafts, STEM and archery (age 7 and up), and children 7 to 12 can add optional weekly field trips.', 'outdoor', NULL, 390, 460, NULL, 'week', NULL, NULL, FALSE, TRUE, 'The $50 weekly deposit is non refundable; other payments are refunded with two weeks'' notice. No refunds for behavior suspensions, illness, weather closures or days a family keeps the child home.', NULL, NULL, NULL, NULL, 2026, '7c349652-fc14-527a-9c96-4aad83370969', 'ymca-camp-boroughs-westborough', ST_GeogFromText('SRID=4326;POINT(-71.6162 42.2695)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ymcaofcm.org/camp-boroughs/','https://www.ymcaofcm.org/wp-content/uploads/2026/01/2026-YMCA-Camp-Boroughs-Parent-Handbook.pdf?x27910']::text[], '2026-11-25', '2026-11-25', TRUE),
('YMCA Camp Foskett', 'YMCA of Central Massachusetts', 'https://www.ymcaofcm.org/camp-foskett/', NULL, 'kmekal@ymcaofcm.org', '508-765-5466', '189 Daniels Road', 'Charlton', 'MA', '01507', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','nature','outdoor','sports','arts']::text[], ARRAY['swim lessons','recreational swim','boating','fishing','nature classes','archery','project adventure','sports','arts and crafts','team building','fireside cooking','talent shows']::text[], NULL, 5, 14, NULL, NULL, 'YMCA day camp on 114 acres beside the South Charlton Reservoir for ages 5 to 14. Campers swim and take lessons at the beach, go boating and fishing, try archery and ropes activities, cook over a fire and do crafts and sports, with a theme each week.', 'outdoor', NULL, 300, 325, 300, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '735b7158-2209-5c39-9a1b-3c8305facccf', 'ymca-camp-foskett-charlton', ST_GeogFromText('SRID=4326;POINT(-71.968 42.1339)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=189+Daniels+Road%2C+Charlton%2C+MA&benchmark=Public_AR_Current&format=json','https://www.ymcaofcm.org/camp-foskett/','https://www.ymcaofcm.org/wp-content/uploads/2026/01/v2-YMCACampFoskett-2026Guide.pdf?x27910']::text[], '2026-11-25', '2026-11-25', TRUE),
('YMCA Camp Lowe', 'YMCA of Central Massachusetts', 'https://www.ymcaofcm.org/camp-lowe/', NULL, NULL, NULL, '132 Fort Pond Inn Rd', 'Lancaster', 'MA', '01523', 'Central & Western Massachusetts', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','outdoor','arts','STEM']::text[], ARRAY['instructional swim','recreational swim','canoeing','sailing','archery','arts and crafts','basketball','soccer','baseball','cheerleading','theater','nature','STEM']::text[], NULL, 8, 14, NULL, NULL, 'YMCA day camp on Fort Pond in Lancaster for ages 8 to 14. Campers swim every day, canoe and sail from the boathouse, shoot archery once or twice a week, and play sports or try theater, cheer, crafts and nature science.', 'outdoor', NULL, 350, NULL, 350, 'week', NULL, NULL, TRUE, TRUE, NULL, NULL, 'Swim test on the first day; daily instructional and free swim within marked areas by level, buddy system with checks every 15 minutes, Red Cross or YMCA certified lifeguards.', TRUE, 'https://www.ymcaofcm.org/camp-lowe/', 2026, '17530ca0-e020-5e57-9a55-b3e96b4da6b7', 'ymca-camp-lowe-lancaster', ST_GeogFromText('SRID=4326;POINT(-71.6756 42.4836)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ymcaofcm.org/camp-lowe/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Naticook', 'Merrimack Parks & Recreation Department', 'https://merrimackparksandrec.org/camp-naticook', 'https://merrimack.recdesk.com/Community/Program?category=48', NULL, '603-420-1662', '116 Naticook Road', 'Merrimack', 'NH', '03054', 'New Hampshire', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['sports & games','arts & crafts','nature exploration & hiking','swimming','American Red Cross swim lessons','canoeing/boating','archery','theater/drama','Friday special events']::text[], NULL, NULL, NULL, 0, 5, 'A town-run traditional day camp at Wasserman Park on Naticook Lake in Merrimack, NH, for children entering Kindergarten through 5th grade. Campers do sports, games, arts and crafts, nature activities, swimming, boating, archery and theater, and a daily hot lunch is included.', NULL, NULL, 375, 375, 375, 'week', TRUE, NULL, TRUE, TRUE, 'Each session requires a $50 non-refundable deposit, and the full balance is due 45 days before the session starts. If you cancel at least 30 days ahead, you lose only the deposit. Cancelling 15–30 days ahead gets a 50% refund of what you paid, minus the deposit, and there are no refunds within 15 days of the start. Transfers to another session have no penalty if made at least 30 days ahead. Medical cancellations within 14 days of the start need a doctor''s letter and get a 50% refund of the remaining amount, minus the deposit.', 'The camp no longer provides one-to-one aides. Campers must be able to take part in their assigned group and tell staff what they need. Families are encouraged to call the camp to discuss fit. For one-to-one support, the camp suggests Camp Allen (Bedford), Recreational Education Center (Londonderry) or Camp Starfish (Rindge).', 'The camp is on Naticook Lake. Campers go on canoe trips and have free swim time at the waterfront and beach. American Red Cross swim lessons are offered at no extra cost (the page''s text says ''Returning for 2025'').', NULL, NULL, 2026, '387b219c-0a8b-5f9e-99f4-88cc902009be', 'camp-naticook-merrimack', ST_GeogFromText('SRID=4326;POINT(-71.5199 42.852)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://merrimackparksandrec.org/camp-naticook']::text[], '2026-11-22', '2026-11-22', TRUE),
('Ashland Summer Day Camp', 'Ashland Parks & Recreation', 'https://ashland.nh.gov/uploads/asdc-flyer-2026.pdf', NULL, 'recreation@ashland.nh.gov', '(603) 968-9209', '99 Main Street', 'Ashland', 'NH', '03217', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['swimming']::text[], ARRAY['park days','beach days','field trips','theme weeks']::text[], NULL, 5, 14, 0, 8, 'A town day camp in Ashland for children entering kindergarten through 8th grade, 8am to 4:30pm on weekdays. Mondays and Wednesdays are park days at L.W. Packard Field, Tuesdays and Thursdays are beach days at the town beach on Little Squam Lake, and Fridays are field trips.', NULL, NULL, 165, 165, 165, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, 'Tuesdays and Thursdays are spent at Ashland Town Beach (Edward N. Doggett Beach) on River Street. The manual gives no swim test details.', NULL, NULL, 2026, 'fdf70774-1511-5b7e-873b-9799e23909ec', 'ashland-summer-day-camp-ashland', ST_GeogFromText('SRID=4326;POINT(-71.6426 43.726)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ashland.nh.gov/uploads/asdc-flyer-2026.pdf','https://ashland.nh.gov/uploads/complete-manuel-2026.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Bow Rec Day Camp', 'Town of Bow Parks & Recreation', 'https://bownh.gov/813/Bow-Rec-Day-Camp', 'https://form.jotform.com/bowrecenter/2026-brc-summer-camp-waitlist-form', 'bowreccenter@bownh.gov', '603-223-3984', '21 Bow Center Rd', 'Bow', 'NH', '03304', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['sports','arts','nature']::text[], ARRAY['arts and crafts','STEM','sports','team building games','field games','water play','nature walks','theme days','field trips']::text[], NULL, 5, 13, 0, 7, 'Town run day camp at the Bow Rec Center for children entering kindergarten through grade 7, open 7:00 to 5:45 on weekdays for ten weeks. Days mix arts and crafts, STEM, sports, field games, water play and nature walks, with paid field trips twice a week for older campers.', 'both', NULL, 180, 265, 225, 'week', NULL, NULL, NULL, NULL, 'No refunds or credits for registration fees, deposits, camp fees or field trip fees. Field trip fees are refunded only if the trip is cancelled.', NULL, NULL, NULL, NULL, 2026, 'd0204098-7ef8-5c27-b61b-487450eeb09a', 'bow-rec-day-camp-bow', ST_GeogFromText('SRID=4326;POINT(-71.5372 43.1332)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bownh.gov/813/Bow-Rec-Day-Camp','https://bownh.gov/DocumentCenter/View/8302/Bow-Rec-Day-Camp-Parent-Handbook-2026','https://bownh.gov/DocumentCenter/View/8304/Bow-Rec-Day-Camp-Flyer-2026']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Bernadette', 'Roman Catholic Diocese of Manchester', 'https://bfcamp.com/camp-bernadette', 'https://berniefatima26.campbrainregistration.com/', 'info@bfcamp.com', '(603) 931-5500', '83 Richards Road', 'Wolfeboro', 'NH', '03894', 'New Hampshire', 'sleepaway', ARRAY['faith','general']::text[], ARRAY['swimming','performing_arts','arts','sports']::text[], ARRAY['swim lessons','swimming','paddleboarding','water trampoline','kayaking','canoeing','tubing','sailing','soccer','gaga','tennis','ultimate','archery','BB guns','high ropes','low ropes','climbing wall','horseback riding','theatre','dance','pottery','arts and crafts','Mass and prayer']::text[], 'girls', NULL, NULL, NULL, NULL, 'Catholic overnight camp for girls on Lake Wentworth in Wolfeboro, run by the Diocese of Manchester since 1953. Campers live in cabins and fill the day with swimming and boating, sports, ropes and climbing, horseback riding, theatre, dance and crafts, along with daily prayer and Mass.', 'outdoor', 'Roman Catholic', 1300, 2500, 1300, 'session', NULL, TRUE, TRUE, TRUE, 'Registration fees ($250 per two week session, $150 per one week session) and card fees are never refunded. Cancel by February 28 and the rest of the tuition is refunded; from March 1 there are no refunds, and none for late arrival or leaving early. A session can be switched at no cost if there is space. Medical cancellations are reviewed case by case with a doctor''s note.', NULL, 'Swim lessons and free swim in the lake, with staff holding American Red Cross Lifeguard certification.', TRUE, 'https://bfcamp.com/safety', 2027, 'e6f41b3f-2ada-513a-90fb-7d6976ae9155', 'camp-bernadette-wolfeboro', ST_GeogFromText('SRID=4326;POINT(-71.1692 43.6144)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bfcamp.com/__l5e/assets-v1/555724e5-5518-4768-9a2f-1723f42f51fa/parent-handbook-2027.pdf','https://bfcamp.com/camp-bernadette','https://bfcamp.com/camp-bernadette/activities','https://bfcamp.com/camp-bernadette/location','https://bfcamp.com/dates-rates','https://bfcamp.com/safety','https://bfcamp.com/transportation']::text[], '2026-11-25', '2026-11-25', TRUE),
('Goffstown Day Camp (Camp Halfmoon)', 'The Granite YMCA', 'https://www.graniteymca.org/camps/day-camp/goffstown/', NULL, 'lfrazier@graniteymca.org', '603.232.8699', '116 Goffstown Back Rd', 'Goffstown', 'NH', '03045', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['outdoor','nature','arts','sports','swimming']::text[], ARRAY['drama','archery','nature exploration','sports','high and low ropes courses','arts and crafts','swimming','field games','climbing','weekly bbq']::text[], NULL, 6, 14, 1, 8, 'Traditional YMCA day camp on ten wooded acres behind the Allard Center in Goffstown for children entering grades 1 to 8. Days include archery, ropes courses, drama at an outdoor amphitheater, sports, crafts, nature trails and swimming, 8:30 to 4:00 with free before and after care.', 'outdoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, 'A $35 deposit per week is not refundable. Cancel more than 6 weeks before the camp week for a full refund less the deposit; 3 to 6 weeks before, a $65 admin fee also applies; less than 3 weeks before, no refund.', NULL, NULL, TRUE, 'https://www.graniteymca.org/camps/day-camp/goffstown/', 2026, 'd0762ce6-14e9-5085-b7e8-27dfa7b456d2', 'camp-halfmoon-goffstown', ST_GeogFromText('SRID=4326;POINT(-71.5554 43.0192)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.graniteymca.org/camps/day-camp/goffstown/','https://www.graniteymca.org/dev/wp-content/uploads/2024/01/Summer-Billing-Schedule.pdf','https://www.graniteymca.org/location/goffstown/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Kettleford', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/kettleford.html', NULL, NULL, NULL, '26 Camp Rd', 'Bedford', 'NH', '03110', 'New Hampshire', 'day', ARRAY['general','nature']::text[], ARRAY['arts','outdoor','leadership','swimming']::text[], ARRAY['crafts','target sports','paddling','swimming','campfire cooking','sing-alongs','nature hikes','low challenge course','theme weeks','badge work']::text[], 'girls', 5, 16, 0, 10, 'Girl Scout day camp on 30 wooded acres by Sandy and Sebbins Ponds in Bedford for girls entering kindergarten through grade 10, with weekly themed programs by grade. Campers do crafts, target sports, paddling, swimming, campfire cooking and hikes; drop off 8:30 to 8:45, pick up 4:00 to 5:00, buses for most weeks.', 'outdoor', NULL, NULL, NULL, 375, 'week', NULL, TRUE, NULL, TRUE, 'A $100 deposit, included in the session price, is not refundable.', NULL, NULL, NULL, NULL, 2027, 'f756f91d-63b7-5864-8d23-d435b31493f8', 'camp-kettleford-bedford', ST_GeogFromText('SRID=4326;POINT(-71.5369 42.9356)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/kettleford.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Seawood', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/seawood.html', NULL, NULL, NULL, '350 Banfield Rd', 'Portsmouth', 'NH', '03801', 'New Hampshire', 'day', ARRAY['general','nature']::text[], ARRAY['arts','outdoor','leadership']::text[], ARRAY['sing-alongs','crafts','target sports','archery','low ropes course','nature hikes','theme weeks']::text[], 'girls', NULL, NULL, 0, 10, 'Girl Scout day camp on 38 acres of woods and wetlands in Portsmouth, with themed weekly programs by grade and a two week Counselor in Training course for older girls. Campers do crafts, archery and target sports, a low ropes course and nature hikes, 9:00 to 5:00.', 'outdoor', NULL, NULL, NULL, 375, 'week', NULL, NULL, NULL, TRUE, 'A $100 deposit, included in the session price, is not refundable.', NULL, NULL, NULL, NULL, 2027, '0b6c6f1d-2188-5c67-87c4-fc7c53fcf610', 'camp-seawood-portsmouth', ST_GeogFromText('SRID=4326;POINT(-70.7626 43.0718)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/seawood.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Souhegan', 'Boys & Girls Club of Souhegan Valley', 'https://www.svbgc.org/summer-camp', 'https://operations.daxko.com/Online/5468/MembershipV2/MyAccountV2.mvc', 'acraven@svbgc.org', '(603) 672-1002', '56 Mont Vernon Street', 'Milford', 'NH', '03055', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['outdoor','nature','swimming']::text[], ARRAY['theme weeks','field trips','outdoor play','free swim','swim lessons']::text[], NULL, 5, 16, 0, 10, 'Boys & Girls Club summer day camp at the Club in Milford for youth in kindergarten to grade 10, by the week or the day for ten weeks. Each week has a theme and field trips, with outdoor play and swimming at Keyes Pool; drop off from 7:00, program 9:00 to 3:30, pick up by 6:00.', 'both', NULL, 75, 300, 300, 'week', TRUE, NULL, NULL, TRUE, 'Cancellations must be made at least 2 weeks in advance; transfers to another week are allowed if there is space.', NULL, 'Free swim and swim lessons through the Club''s partnership with Keyes Pool.', NULL, NULL, 2026, 'b7a1dc93-6180-53ce-8595-02837bc3c696', 'camp-souhegan-milford', ST_GeogFromText('SRID=4326;POINT(-71.6734 42.8186)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=56+Mont+Vernon+Street%2C+Milford%2C+NH&benchmark=Public_AR_Current&format=json','https://www.svbgc.org/summer-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Trek Teen Adventure Camp', 'Merrimack Parks & Recreation Department', 'https://merrimackparksandrec.org/camp-trek', 'https://merrimack.recdesk.com/Community/Program?category=49', NULL, '603-420-1662', NULL, 'Merrimack', 'NH', '03054', 'New Hampshire', 'day', ARRAY['adventure']::text[], ARRAY['outdoor','sports']::text[], ARRAY['daily field trips','state park hikes and beaches','paddleboarding','trampoline park','amusement parks','ninja gym','roller skating','bowling','minor league baseball game','museum trips']::text[], NULL, NULL, NULL, 5, 9, 'Town run trip camp in Merrimack for kids entering grades 5 to 9, offered as an alternative to the Naticook day camp. Each weekday the group goes on a field trip somewhere in New England, such as state parks and beaches, paddleboarding, trampoline parks, amusement parks and ball games.', 'both', NULL, 355, 405, 405, 'week', TRUE, TRUE, NULL, TRUE, 'Each session has a $50 nonrefundable deposit and the balance is due 45 days before it starts. Cancel at least 30 days ahead and lose only the deposit; 15 to 30 days ahead, get 50% of what was paid less the deposit; no refunds within 15 days. Medical cancellations with a doctor''s letter get 50% of the remainder less the deposit.', NULL, NULL, NULL, NULL, 2026, 'f0174e40-1afb-5665-8d14-b33cc32876e2', 'camp-trek-merrimack', ST_GeogFromText('SRID=4326;POINT(-71.5199 42.852)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://merrimackparksandrec.org/camp-trek']::text[], '2026-11-25', '2026-11-25', TRUE),
('Flights of Discovery Summer Camp', 'Aviation Museum of N.H.', 'https://aviationmuseumofnh.org/education/summer-camp/', NULL, 'nmacdonald@nhahs.org', '(603) 669-4820 ext. 405', '27 Navigator Road', 'Londonderry', 'NH', '03053', 'New Hampshire', 'specialty', ARRAY['STEM']::text[], ARRAY['academic']::text[], ARRAY['aviation history','aerospace engineering','flight simulation','weather forecasting','air traffic control','field trips']::text[], NULL, 10, 17, NULL, NULL, 'Two week aviation day camp at the Aviation Museum of New Hampshire in Londonderry, with separate sessions for ages 10 to 13 and 14 to 17 and at most 20 campers each. Campers study aviation history, aerospace engineering, flight simulation, weather and air traffic control, with three field trips such as airport and air base visits; 9:00 to 4:00.', 'indoor', NULL, 1400, 1400, NULL, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '7c127668-b39d-5f4c-8176-ffe2392549a6', 'flights-of-discovery-summer-camp-londonderry', ST_GeogFromText('SRID=4326;POINT(-71.3923 42.8798)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://aviationmuseumofnh.org/education/summer-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Horton Center', 'New Hampshire Conference, United Church of Christ', 'https://www.hortoncenter.org/sessions', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=463&campCode=hnc', 'info@hortoncenter.org', '(603) 545-9660', 'Pine Mountain Horton Center Rd', 'Gorham', 'NH', '03581', 'New Hampshire', 'sleepaway', ARRAY['faith','outdoor']::text[], ARRAY['adventure','arts']::text[], ARRAY['hiking','caving','rock climbing','archery','swimming','arts and crafts','music','games','chapel']::text[], NULL, NULL, NULL, 3, 12, 'Overnight church camp on Pine Mountain near Gorham in the White Mountains, run by the New Hampshire Conference of the United Church of Christ. Kids entering grades 3 to 12 come for week long sessions grouped by grade, with hiking, caving, rock climbing, swimming, archery and crafts alongside daily chapel and open faith discussion.', 'outdoor', 'United Church of Christ', 240, 750, 750, 'session', NULL, FALSE, TRUE, TRUE, NULL, 'Families should tell the directors about any physical, emotional or behavioral needs before registering by contacting the executive director. The camp says it cannot serve every need but tries to support as many campers as it can.', NULL, TRUE, 'https://www.hortoncenter.org/sessions', 2026, '7ba1c62f-7967-5e36-b441-6adc943ccf9c', 'horton-center-gorham', ST_GeogFromText('SRID=4326;POINT(-71.1985 44.3934)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.hortoncenter.org/directions','https://www.hortoncenter.org/faq','https://www.hortoncenter.org/register','https://www.hortoncenter.org/sessions']::text[], '2026-11-25', '2026-11-25', TRUE),
('Kimball Jenkins Summer Art Camp', 'Kimball Jenkins School of Art', 'https://www.kimballjenkins.com/', NULL, 'lindsay@kimballjenkins.com', '603-225-3932', '266 N. Main St.', 'Concord', 'NH', '03301', 'New Hampshire', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['painting','drawing','mixed media','character design','wearable art','art exhibition']::text[], NULL, 6, 14, NULL, NULL, 'Art day camp at Kimball Jenkins in Concord, run in two week themed sessions. Campers aged 6 to 14 take three art classes a day with Kimball Jenkins faculty, grouped by age, and show their work in the historic mansion on the last Friday.', 'indoor', NULL, 700, 725, NULL, 'session', TRUE, NULL, FALSE, TRUE, 'Cancellations 30 or more days before a session get a full refund less a $50 fee. Later cancellations are refunded only if the spot is filled from the waitlist, with case by case review for serious illness or family emergency. Families can instead donate the tuition or take a credit for another youth program.', NULL, NULL, NULL, NULL, 2026, '9b0c8789-3cdc-5fb1-b161-1b32a7a3a85f', 'kimball-jenkins-summer-art-camp-concord', ST_GeogFromText('SRID=4326;POINT(-71.5376 43.2081)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.kimballjenkins.com/','https://www.kimballjenkins.com/UploadedFiles/Images/Kimball%20Jenkins%20Camp%20Handbook%202026.docx.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Little River Summer Camp', 'Southern District YMCA', 'https://www.sdymca.org/little-river', 'https://operations.daxko.com/Online/5279/ProgramsV2/Search.mvc?category_ids=CAT1095', 'SACCinfo@sdymca.org', '603-319-5937', '30 Linden Street', 'Exeter', 'NH', '03833', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['sports','outdoor']::text[], ARRAY['theme weeks','zumba','pound','yoga','field trips','trips to camp lincoln']::text[], NULL, 5, 11, 0, 5, 'YMCA day camp at the Tuck Learning Center in Exeter for children in kindergarten to grade 5, in one week sessions over eight weeks, 8:00 to 4:00. Each week has a theme, a field trip, YMCA fitness classes and a trip to Camp Lincoln in Kingston.', 'both', NULL, NULL, NULL, 329, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '5db56a5e-c082-58c4-88c2-9cb5119ea2e0', 'little-river-summer-camp-exeter', ST_GeogFromText('SRID=4326;POINT(-70.9479 42.9812)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=30+Linden+Street%2C+Exeter%2C+NH&benchmark=Public_AR_Current&format=json','https://www.sdymca.org/little-river','https://www.sdymca.org/summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('R.E.A.C.H. Camp', 'Oyster River Cooperative School District and Durham Parks & Recreation', 'https://durhamrec.recdesk.com/RecDeskPortal/Portals/248/2026%20REACH%20Catalog.pdf', 'https://durhamrec.recdesk.com/Community/Home', 'recreation@ci.durham.nh.us', '(603) 817-4074', NULL, 'Durham', 'NH', '03824', 'New Hampshire', 'day', ARRAY['general']::text[], ARRAY['arts','STEM','sports']::text[], ARRAY['robotics','crafts','science experiments','cooking','field hockey','chess','musical theater','swimming','friday field trips']::text[], NULL, 6, 14, 1, 8, 'A Monday to Thursday summer camp at Oyster River Middle School in Durham for children entering 1st to 8th grade. Mornings are school district enrichment camps such as robotics, crafts, cooking and sports, and afternoons with Durham Parks & Recreation bring games, crafts, water play and swimming, with optional Friday field trips.', NULL, NULL, 130, 275, 275, 'week', NULL, NULL, NULL, NULL, 'Cancel by April 30 for a full refund or credit, May 1 to 31 for 50%, and from June 1 with two weeks notice for a 50% account credit only. Later cancellations get nothing back.', NULL, 'Afternoon camp includes water activities and swimming, and some weeks visit Wellington State Park or Great Island Common. The guide gives no swim test details.', NULL, NULL, 2026, '0dccb0c6-4fc5-5e60-95f2-9806e786e833', 'r-e-a-c-h-camp-durham', ST_GeogFromText('SRID=4326;POINT(-70.9188 43.1171)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://durhamrec.recdesk.com/Community/Page?pageId=9892','https://durhamrec.recdesk.com/RecDeskPortal/Portals/248/2026%20REACH%20Catalog.pdf']::text[], '2026-11-25', '2026-11-25', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Farm Camp at Adams Farm', 'Adams Farm', 'https://www.adamsfarmri.com/farm-camp', 'https://www.simpletix.com/e/farm-camp-2026-tickets-250370', 'farmer@adamsfarmri.com', '401-333-5001', '495 Sumner Brown Rd.', 'Cumberland', 'RI', '02864', 'Providence, RI', 'day', ARRAY['nature']::text[], ARRAY['outdoor']::text[], ARRAY['animal care','nature walks','scavenger hunts','garden activities','crafts','free play']::text[], NULL, 6, 12, NULL, NULL, 'A weekly farm day camp in Cumberland where children feed and groom farm animals, garden, take nature walks and make farm themed crafts.', NULL, NULL, 400, 400, 400, 'week', TRUE, NULL, FALSE, NULL, 'Refunds for cancellations made before May 1, 2026; week exchanges depend on availability.', NULL, NULL, NULL, NULL, 2026, 'e00e8798-d107-58ff-ac5e-e745540284a6', 'adams-farm-camp-cumberland', ST_GeogFromText('SRID=4326;POINT(-71.4328 41.9668)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.adamsfarmri.com/farm-camp','https://www.adamsfarmri.com/uploads/b/1ea3c4f0-8505-11ea-8046-cdee9d622d4f/a11afd30-eb10-11f0-a446-27ac161e3e36.pdf','https://www.simpletix.com/e/farm-camp-2026-tickets-250370']::text[], '2026-11-25', '2026-11-25', TRUE),
('Arts Alive! Summer Camp', 'Arts Alive! Barrington', 'https://artsaliveri.org/summer-camp-performing-arts/', NULL, 'admin@artsalivebarrington.org', '(401) 237-0638', 'St. John''s Episcopal Church, 191 County Rd', 'Barrington', 'RI', '02806', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['theater games','improv','stage makeup','dance','creative movement','voice','mask making','stage combat','theatre craft and design']::text[], NULL, 8, 14, 3, 8, 'One week theater camps in Barrington where students entering grades 3 to 8 play theater games and improv, try dance, voice and stage makeup, and give a show for families at the end of each week.', NULL, NULL, 375, 375, 375, 'week', NULL, NULL, NULL, TRUE, 'Full refund minus a $30 fee if you withdraw more than 72 hours before camp; 50% refund within 72 hours (full minus $30 if the spot is filled from the waitlist); no refund once camp starts.', NULL, NULL, NULL, NULL, 2027, 'dbad0945-079d-5ff2-b228-137cc644a6ac', 'arts-alive-summer-camp-barrington', ST_GeogFromText('SRID=4326;POINT(-71.309 41.7412)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://artsaliveri.org/contact-us/','https://artsaliveri.org/summer-camp-performing-arts/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Greenside', 'Boys & Girls Clubs of Metro South', 'https://www.bgcmetrosouth.org/camp-greenside', NULL, NULL, '508-824-4341', '31 Court Street (Taunton Clubhouse)', 'Taunton', 'MA', '02780', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM','swimming']::text[], ARRAY['sports','games','arts and crafts','drama','dance','pool','playground','STEM','educational enrichment','theme days']::text[], NULL, 5, 12, NULL, NULL, 'A building based summer day camp at the Boys and Girls Club''s Taunton Clubhouse on Court Street, with weekly themes. Campers must be club members.', NULL, NULL, 215, 215, 215, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'ccd915b2-879b-5f83-b264-5f49dfdbe9c3', 'camp-greenside-taunton', ST_GeogFromText('SRID=4326;POINT(-71.0898 41.9001)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bgcmetrosouth.org/camp-greenside','https://www.taunton-ma.gov/DocumentCenter/View/7073/2026-Camp-Greenside_Updated-Dates']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp TBTS', 'Theatre By The Sea', 'https://www.theatrebythesea.com/camp.html', NULL, NULL, '(401) 782-8587', '450 Woodruff Avenue (rehearsal studio)', 'Wakefield', 'RI', '02879', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['musical theatre','rehearsals','staged musical production']::text[], NULL, 10, 16, NULL, NULL, 'A two week musical theatre camp for ages 10 to 16 at Theatre By The Sea''s Wakefield rehearsal studio, ending with a staged youth musical on the main stage.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '7b7e980b-d4dd-5714-8083-880da2260cc2', 'camp-tbts-wakefield', ST_GeogFromText('SRID=4326;POINT(-71.5017 41.4373)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.theatrebythesea.com/camp.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Cast No Shadows Stables Summer Camp', 'Cast No Shadows Stables, LLC', 'https://www.castnoshadows.com/camps.html', NULL, 'allie@castnoshadows.com', '(401) 443-7697', '542 Spring St, Rockville', 'Hopkinton', 'RI', '02873', 'Providence, RI', 'specialty', ARRAY['outdoor']::text[], ARRAY['nature']::text[], ARRAY['horseback riding','horse care','barn chores','games','trail riding']::text[], NULL, 5, NULL, NULL, NULL, 'Week long horse camps at a stable in the Rockville village of Hopkinton for kids 5 and up of any riding level, with riding, horse care, barn chores and games. Summer weeks alternate between Rodeo and Horsemanship themes, plus one overnight sleepover camp.', 'outdoor', NULL, 400, 800, 400, 'week', TRUE, NULL, NULL, NULL, 'Free cancellation up to 24 hours before camp starts.', NULL, NULL, NULL, NULL, 2027, '619d4bf7-0dc8-51e0-a609-9cd70a77f04e', 'cast-no-shadows-stables-summer-camp-hopkinton', ST_GeogFromText('SRID=4326;POINT(-71.7579 41.4791)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.castnoshadows.com/camps.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Courage Quest', 'Child Anxiety Program', 'https://www.childanxietyprogram.com/summer-camp', 'https://www.childanxietyprogram.com/pre-registration', 'efschroeder@uri.edu', '401-874-4219', 'University of Rhode Island, Chafee Hall, Suite 100', 'Kingston', 'RI', '02881', 'Providence, RI', 'specialty', ARRAY['special_needs']::text[], NULL, ARRAY['themed adventures','games','hands-on activities','coping skills practice','exposure practice']::text[], NULL, 8, 12, NULL, NULL, 'A small therapeutic day camp at URI in Kingston for children with mild to moderate anxiety. Campers play games, take on themed challenges and practice coping skills such as breathing, self talk and facing fears step by step, led by a licensed psychologist.', NULL, NULL, 575, 575, 575, 'week', NULL, FALSE, FALSE, TRUE, 'Full refund minus a $50 fee for cancellations at least 30 days before camp starts; no refunds after that except for documented medical emergencies.', 'Built for children with mild to moderate anxiety, including those already diagnosed. About 3 campers per staff member. No nurse on site; staff trained in first aid and CPR. Nut free.', NULL, NULL, NULL, 2027, 'd74b1d5f-13a4-5b1d-9ceb-1d671ee861c7', 'courage-quest-summer-camp-kingston', ST_GeogFromText('SRID=4326;POINT(-71.5242 41.4801)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.childanxietyprogram.com/faq','https://www.childanxietyprogram.com/summer-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Federal Hill House Summer Camp', 'Federal Hill House', 'https://www.federalhillhouse.org/programs/summer-camp/', 'https://www.myprocare.com/Default/Index?aWtuPTgyMjg1MDAwMTUmc2NoSWQ9MQ=', 'SummerCamp@federalhillhouse.org', '(401) 421-4722', '35 Swiss Street', 'Providence', 'RI', '02909', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['arts','sports','swimming']::text[], ARRAY['weekly themes','outdoor play','arts and crafts','makerspace','team sports','games','swimming','field trips']::text[], NULL, 6, 13, 1, 7, 'A full day summer camp at Federal Hill House in Providence for kids entering grades 1 to 7, with weekly themes, arts and crafts in the makerspace, team games, outdoor play, swimming and field trips by van.', 'both', NULL, NULL, NULL, 287.5, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'c8d1c382-b067-59da-9252-183a51e608ad', 'federal-hill-house-summer-camp-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=35+Swiss+Street%2C+Providence%2C+RI&benchmark=Public_AR_Current&format=json','https://www.federalhillhouse.org/programs/summer-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Newport Sings Summer Camp', 'Newport Sings', 'https://www.newportsings.org/summer-camp', 'https://www.newportsings.org/summer-camp-registration', 'sing@newportsings.org', NULL, 'Channing Memorial Church, 135 Pelham St', 'Newport', 'RI', '02840', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['singing','music','art','movement','performance']::text[], NULL, 7, 12, 2, 6, 'A one week singing camp in Newport for students entering grades 2 to 6, who sing, make art and move together and then perform for family and friends.', NULL, NULL, 225, 345, 295, 'week', NULL, NULL, NULL, TRUE, 'Before June 1: full refund less 10%. June 1 to July 26: full refund less 15% if the spot is filled, otherwise 50%. July 27 or later: no refund.', NULL, NULL, NULL, NULL, 2026, 'dc7c6815-57b9-5f28-8ac4-6e8f7aac3e34', 'newport-sings-summer-camp-newport', ST_GeogFromText('SRID=4326;POINT(-71.3128 41.4901)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.newportsings.org/summer-camp']::text[], '2026-11-25', '2026-11-25', TRUE),
('Saunderstown Yacht Club Junior Sailing Program', 'Saunderstown Yacht Club', 'https://saunderstownyachtclub.org/home-public/junior-sailing-public/', 'https://form.jotform.com/waterwayext/2026-syc-non-member-junior-sailing-', 'sycsailingchair@gmail.com', NULL, NULL, 'Saunderstown', 'RI', '02874', 'Providence, RI', 'specialty', ARRAY['sailing']::text[], ARRAY['STEM']::text[], ARRAY['sailing','marine science','racing','swimming','art projects','games']::text[], NULL, 8, NULL, NULL, NULL, 'Junior sailing classes for non members on the West Passage of Narragansett Bay, from beginner Blue Dragon boats with marine science activities to Optimist and 420 racing.', NULL, NULL, 750, 1800, NULL, 'session', NULL, NULL, NULL, NULL, '$50 charge for cancellations or changes up to the first week of class; no refunds after that.', NULL, 'Every junior sailor takes a swim test on the first day; life jackets are mandatory.', NULL, NULL, 2026, '2f8bd983-86a3-54d5-853d-478c9b609084', 'saunderstown-yacht-club-junior-sailing-saunderstown', ST_GeogFromText('SRID=4326;POINT(-71.4359 41.5126)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://saunderstownyachtclub.org/home-members/contact/','https://saunderstownyachtclub.org/home-public/junior-sailing-public/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Camp at Newport Art Museum', 'Newport Art Museum', 'https://newportartmuseum.org/classes/summer-camp-at-newport-art-museum/', NULL, 'mhickey@newportartmuseum.org', '401-619-7983', '26 Liberty Street (Coleman Center for Creative Studies)', 'Newport', 'RI', '02840', 'Providence, RI', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['artmaking','gallery visits','creative games','guided discussions','weekly camper art show']::text[], NULL, NULL, NULL, NULL, NULL, 'Weekly art camps at the Newport Art Museum''s school on Liberty Street. Each week has a theme drawn from the museum''s exhibitions and collection, with hands-on projects, gallery visits and games, and ends with a small Friday show of camper work.', 'both', NULL, NULL, NULL, NULL, NULL, FALSE, NULL, FALSE, TRUE, 'Refund up to two weeks before the camp starts, less a $25 processing fee. No refunds for missed days or for children removed for behavior.', 'Families needing accommodations should contact the Director of Museum Education at registration, ideally two weeks ahead. Campers must be fully potty trained. Staff cannot give medication.', NULL, NULL, NULL, 2027, 'de70d8d9-c742-5aec-991b-f1d873e661e8', 'summer-camp-at-newport-art-museum-newport', ST_GeogFromText('SRID=4326;POINT(-71.3128 41.4901)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://newportartmuseum.org/classes/summer-camp-at-newport-art-museum/','https://pub-f2d8c5d7792541cd93b46421e64ec523.r2.dev/wp-content/uploads/2025/05/Summer-Camp-FAQ.pdf','https://pub-f2d8c5d7792541cd93b46421e64ec523.r2.dev/wp-content/uploads/2025/05/Summer-Camp-Policies-and-Procedures.pdf']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Festival', 'Taunton Parks & Recreation', 'https://www.taunton-ma.gov/993/Summer-CampsPrograms', 'https://tauntonma.myrec.com/', NULL, '508-821-1415', 'Hopewell Park', 'Taunton', 'MA', '02780', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['swimming','arts and crafts','sports','games','weekly field trips']::text[], NULL, 5, 12, NULL, NULL, 'The city''s outdoor summer program at Hopewell Park for Taunton children, with swimming at Hopewell Pool, sports, crafts, games and a field trip each week. Breakfast and lunch are served, and it moves to the former Coyle and Cassidy gym on rainy days.', 'outdoor', NULL, 160, 200, 160, 'week', TRUE, NULL, TRUE, TRUE, NULL, NULL, 'Campers swim at Hopewell Pool.', NULL, NULL, 2026, '6f15b9b5-5d6d-57e2-b533-5b2abbe03b89', 'summer-festival-taunton', ST_GeogFromText('SRID=4326;POINT(-71.0898 41.9001)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.taunton-ma.gov/993/Summer-CampsPrograms','https://www.taunton-ma.gov/DocumentCenter/View/7048/Parks-and-Recreation-Summer-Flyer-2026']::text[], '2026-11-25', '2026-11-25', TRUE),
('United Sports Arena Recreational Summer Camp', 'United Sports Arena', 'https://www.unitedsportsarena.com/cricket-camps', 'https://www.unitedsportsarena.com/shop/summer-camp-2026-6549', 'contactus@unitedsportsarena.com', '(508) 709-5635', '839 Upper Union Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['cricket','batting','bowling','fielding','box cricket','futsal','lego','puzzles','reading']::text[], 'coed', 5, NULL, NULL, NULL, 'An indoor cricket camp at United Sports Arena in Franklin for boys and girls 5 and up, all skill levels, grouped by age (5 to 9 and 10 plus). Days mix batting, bowling and fielding drills and box cricket games with free choice time for Lego, puzzles, futsal or reading.', 'indoor', NULL, 225, 399, 399, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '53918df9-4ec3-566b-895f-533faee93c67', 'united-sports-arena-recreational-summer-camp-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.unitedsportsarena.com/cricket-camps','https://www.unitedsportsarena.com/shop/summer-camp-2026-6549']::text[], '2026-11-25', '2026-11-25', TRUE),
('URI Summer Music Academy', 'University of Rhode Island Music Department', 'https://sites.google.com/uri.edu/urisma/home', NULL, 'alacasse@uri.edu', NULL, 'URI Kingston campus, 105 Upper College Road', 'Kingston', 'RI', '02881', 'Providence, RI', 'sleepaway', ARRAY['performing_arts']::text[], NULL, ARRAY['large ensemble','chamber ensemble','studio classes','music theory','masterclasses','beach trip','evening activities']::text[], NULL, NULL, NULL, 7, 12, 'A one or two week band, orchestra and choir camp on URI''s Kingston campus for students who have finished grades 7 to 12, with ensembles, studio classes and theory, as residents in campus dorms or as commuters.', NULL, NULL, 1050, 3500, 1675, 'session', NULL, NULL, TRUE, TRUE, 'Cancellation fee is 50% of tuition from June 19 to June 30, 2027 and 100% from July 1 to August 1, 2027.', NULL, NULL, NULL, NULL, 2027, 'a98d064b-11c4-5d89-81fc-f8b1e4a82feb', 'uri-summer-music-academy-kingston', ST_GeogFromText('SRID=4326;POINT(-71.5242 41.4801)'), FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://sites.google.com/uri.edu/urisma/home']::text[], '2026-11-25', '2026-11-25', TRUE),
('AllTogetherNow! Summer Camps', 'AllTogetherNow!', 'https://www.alltogethernowvt.org/summer_camps.html', 'https://www.activityhero.com/biz/alltogethernow?aht_cam=schedule-widget&aht_src=84621&brand=1', NULL, '802-223-1242', '20 Wyvern Way', 'East Montpelier', 'VT', '05651', 'Vermont', 'day', ARRAY['arts','nature']::text[], ARRAY['swimming']::text[], ARRAY['swimming','art','stilt walking','singing','storytelling','cooperative games','herbal crafts','music','fiber arts','hiking']::text[], NULL, 3, 12, NULL, NULL, 'Weekly themed day camps in central Vermont, Monday to Friday 9am to 3pm, mostly outdoors. Campers make art, sing, play cooperative games, learn stilt walking and swim daily in a saltwater pool, with weeks on herbs, rock music, fiber crafts and making.', 'both', NULL, 365, 400, 365, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, 'Daily swim time in an in-ground saltwater pool (3 feet shallow, 8 feet deep, separated by a rope) with a licensed lifeguard on duty. Parents choose no pool, shallow end only, or full pool after a swim test.', NULL, NULL, 2026, '4c52b3d0-c659-57cf-a95f-64ecf508ede1', 'alltogethernow-summer-camps-east-montpelier', ST_GeogFromText('SRID=4326;POINT(-72.5069 44.2961)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.alltogethernowvt.org/contact_us.html','https://www.alltogethernowvt.org/summer_camps.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Camp Twin Hills', 'Girl Scouts of the Green and White Mountains', 'https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/twin-hills.html', NULL, 'customercare@girlscoutsgwm.org', '888-474-9686', '2428 Wes White Hill', 'Richmond', 'VT', '05477', 'Vermont', 'day', ARRAY['outdoor']::text[], ARRAY['leadership','arts','STEM']::text[], ARRAY['campfire cooking','hiking','sing alongs','theme weeks','crafts','science experiments','leadership training']::text[], 'girls', NULL, NULL, 0, 10, 'A Girl Scout day camp on 184 wooded acres in Richmond, between Burlington and Montpelier, for girls entering kindergarten through 10th grade. Theme weeks mix crafts, science and fantasy with camp favorites like hiking, campfire cooking and sing alongs, and older girls can train as program aides or counselors in training.', 'outdoor', NULL, 200, 600, 375, 'session', NULL, TRUE, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '73fa36ea-b552-564e-be07-492ab812fb98', 'camp-twin-hills-richmond', ST_GeogFromText('SRID=4326;POINT(-72.9796 44.382)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.girlscoutsgwm.org/en/activities/camp-and-outdoors/twin-hills.html']::text[], '2026-11-25', '2026-11-25', TRUE),
('Catamount Outdoor Family Center Summer Camps', 'Catamount Outdoor Family Center', 'https://catamountoutdoor.org/camps/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=1440&campCode=98F', 'thehub@catamountoutdoor.org', '802-879-6001', '592 Governor Chittenden Road', 'Williston', 'VT', '05495', 'Vermont', 'specialty', ARRAY['sports','outdoor']::text[], ARRAY['nature']::text[], ARRAY['mountain biking','nature exploration','wildlife tracking','plant identification','survival skills','hiking','field games']::text[], NULL, 6, 14, NULL, NULL, 'Full day mountain biking and nature camps on the Catamount trail network in Williston for ages 6 to 14, 8:30am to 4pm. Options include a combo bike and nature camp for ages 6 to 7, Explorers, Mountain Bike and Advanced Mountain Bike camps. Campers must already ride without training wheels.', 'outdoor', NULL, 385, 425, 385, 'week', NULL, NULL, NULL, NULL, 'Cancel before June 1 for a refund minus a $50 fee. From June 1 to two weeks before the session, 50% refund. No refund within two weeks of the session or for campers sent home for lacking the required bike skills.', NULL, NULL, NULL, NULL, 2026, '87001094-74ef-5a36-814e-ee08339f475d', 'catamount-outdoor-family-center-summer-camps-williston', ST_GeogFromText('SRID=4326;POINT(-73.0963 44.4292)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://catamountoutdoor.org/camps/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Summer Adventure Camp', 'Common Ground Center', 'https://cgcvt.org/youth-camps/day-camps/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=935&campcode=nd2&lang=en-Us', 'info@cgcvt.org', '802.453.2592', '473 Tatro Road', 'Starksboro', 'VT', '05487', 'Vermont', 'day', ARRAY['nature','outdoor']::text[], ARRAY['arts','swimming']::text[], ARRAY['archery','tennis','swimming','pond and creek exploring','wildlife identification','hiking','gardening','cooking','music','arts']::text[], NULL, 5, 12, 0, 6, 'A one week summer day camp at Common Ground Center in Starksboro for kids in grades K to 6, 8:30am to 4pm. Outdoors campers do archery, tennis, swimming, hiking and gardening and explore the pond and creek; indoors they cook, play music and make art.', NULL, NULL, 385, 385, 385, 'week', NULL, TRUE, NULL, TRUE, 'Cancellations get a credit toward a future Common Ground Center program, good for one year and usable by immediate family only.', NULL, NULL, NULL, NULL, 2027, 'c510c026-2782-5544-8cd9-c979b42fb3ec', 'common-ground-center-summer-adventure-camp-starksboro', ST_GeogFromText('SRID=4326;POINT(-72.9934 44.2103)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://cgcvt.org/youth-camps/day-camps/']::text[], '2026-11-25', '2026-11-25', TRUE),
('EarthWalk Summer Camps', 'EarthWalk', 'https://www.earthwalktogethervt.org/programs/summercamps', 'https://www.earthwalktogethervt.org/newcamperapplication', 'admin@earthwalktogethervt.org', NULL, '3072 Thaddeus Stevens Road', 'Danville', 'VT', '05828', 'Vermont', 'day', ARRAY['nature','outdoor']::text[], ARRAY['leadership']::text[], ARRAY['naturalist skills','shelter building','fire making','wood carving','wild snacks','games','stories','songs','trail stewardship']::text[], NULL, 6, 16, NULL, NULL, 'Small group forest camps at the Fairbanks Museum Nature Preserve at Matsinger Forest in Danville, 9am to 3pm on weekdays. Forest Explorers (ages 6 to 9) and Forest Adventurers (9 to 12) learn naturalist and outdoor skills like shelter building, fire making and wood carving, and a Teen Leaders week (13 to 16) builds trails and bridges.', 'outdoor', NULL, 385, 735, 385, 'session', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'd0e22a12-a51c-5b25-b5b0-448e23a629d4', 'earthwalk-summer-camps-danville', ST_GeogFromText('SRID=4326;POINT(-72.1248 44.4375)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://fairbanksmuseum.org/matsinger-forest/','https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?address=3072+Thaddeus+Stevens+Road%2C+Danville%2C+VT&benchmark=Public_AR_Current&format=json','https://www.earthwalktogethervt.org/programs/summercamps']::text[], '2026-11-25', '2026-11-25', TRUE),
('Mater Christi School Summer Camp', 'Mater Christi School', 'https://mcschool.org/school-life/summer-camp/', 'https://docs.google.com/forms/d/e/1FAIpQLSehZRMDKOq5R6gFzcn5WnWSxcrDb9G1u1d_pcMGUKGSZrObaw/viewform', NULL, '802-658-3992', '50 Mansfield Avenue', 'Burlington', 'VT', '05401', 'Vermont', 'day', ARRAY['general']::text[], NULL, ARRAY['themed weeks','arts and crafts','STEAM projects','dramatic play','outdoor play','Friday swim','hiking','field trips']::text[], NULL, 3, 9, NULL, NULL, 'A themed weekly day camp at Mater Christi School in Burlington for young children, 8am to 3pm. Each week has a theme such as dragons, ocean life, space or dinosaurs, with art, stories, experiments and outdoor play.', NULL, 'Catholic', 425, 425, 425, 'week', NULL, NULL, NULL, NULL, 'Full refund with two weeks'' notice before the start of the camp week.', NULL, 'Several weeks include a Friday swim at Maple Street Pool in Essex. The page gives no supervision details.', NULL, NULL, 2026, 'f51f1c99-1b5e-5e84-8b99-e71131b093e7', 'mater-christi-school-summer-camp-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://docs.google.com/forms/d/e/1FAIpQLSehZRMDKOq5R6gFzcn5WnWSxcrDb9G1u1d_pcMGUKGSZrObaw/viewform','https://mcschool.org/school-life/summer-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Nature Explorers Summer Camp', 'Bonnyvale Environmental Education Center', 'https://beec.org/day-camps/', NULL, NULL, '802-257-5785', '1221 Bonnyvale Road', 'Brattleboro', 'VT', '05303', 'Vermont', 'day', ARRAY['nature','outdoor']::text[], NULL, ARRAY['hiking','naturalist skills','non-competitive games','water slide','art','music','journaling','stories','free play']::text[], NULL, 4, 11, NULL, NULL, 'A week by week nature day camp for ages 4 to 11 on Bonnyvale Environmental Education Center''s 60 acres of forest, meadow and ponds in West Brattleboro. Campers spend most of the day outside in small groups by age, hiking, learning naturalist skills, playing games, making art and music, and riding the water slide.', 'both', NULL, 400, 400, 400, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'f8d3117b-2288-54f5-b2c3-0e7e8f1e74c9', 'nature-explorers-summer-camp-brattleboro', ST_GeogFromText('SRID=4326;POINT(-72.6331 42.8602)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://beec.org/day-camps/','https://beec.org/event/nature-explorers-summer-camp-8/']::text[], '2026-11-25', '2026-11-25', TRUE),
('Otter Day Camp', 'Vermont Wilderness School', 'https://vermontwildernessschool.org/otter-day-camp/', NULL, 'office@vermontwildernessschool.org', '(802) 257-8570', NULL, 'Brattleboro', 'VT', '05303', 'Vermont', 'day', ARRAY['nature','outdoor']::text[], NULL, ARRAY['fire making','shelter building','cooking over a fire','nature crafts','berry picking','creek exploring','nature awareness games','stalking and moving silently']::text[], NULL, 7, 12, NULL, NULL, 'A wilderness skills day camp at Fort Dummer State Park in Brattleboro for ages 7 to 12, 9am to 3pm. Campers make fire without matches, build shelters, cook over a campfire, explore creeks and play nature awareness games.', 'outdoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '54ab55db-5d37-57da-93bb-719f07c12fad', 'otter-day-camp-brattleboro', ST_GeogFromText('SRID=4326;POINT(-72.6331 42.8602)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://vermontwildernessschool.org/otter-day-camp/']::text[], '2026-11-25', '2026-11-25', TRUE),
('School''s Out Summer Day Camp', 'School''s Out, South Burlington School District', 'https://sites.google.com/sbschools.net/schools-out/our-programs/school-age-summer-camps', NULL, NULL, NULL, NULL, 'South Burlington', 'VT', '05403', 'Vermont', 'day', ARRAY['general']::text[], ARRAY['arts','STEM']::text[], ARRAY['field trips','reading','art','STEM','gym','clubs','outdoor play']::text[], NULL, NULL, NULL, 1, 4, 'The South Burlington School District''s summer day camp for children finishing kindergarten through 3rd grade, held at Rick Marcotte Central School and Orchard Elementary School, 8am to 5:30pm. Days mix a reading block, art, STEM, gym and outdoor time, with two or three field trips each week.', NULL, NULL, 280, 285, 285, 'week', NULL, NULL, FALSE, TRUE, 'Withdrawing with less than two weeks notice means paying that week in full. The $50 deposit per child per week is non-refundable and non-transferable.', NULL, NULL, NULL, NULL, 2026, 'abff86d9-9809-5d8f-a25b-0412d0cde77f', 'schools-out-summer-day-camp-south-burlington', ST_GeogFromText('SRID=4326;POINT(-73.1826 44.4365)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://sites.google.com/sbschools.net/schools-out/our-programs/school-age-summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('School''s Out TREK Camps', 'School''s Out, South Burlington School District', 'https://docs.google.com/document/d/1-yJcmCKXQ_6rEcfxr5b1oBcKgqKvpIZIR7cN4ZmLRQU/edit?usp=sharing', NULL, NULL, NULL, NULL, 'South Burlington', 'VT', '05403', 'Vermont', 'day', ARRAY['general']::text[], ARRAY['outdoor','arts','STEM','sports']::text[], ARRAY['field trips','hiking','cooking','music and songwriting','martial arts','dance','STEM','swimming trips']::text[], NULL, NULL, NULL, 5, 9, 'Week long themed day camps for South Burlington students entering 5th grade and up, based at Frederick H. Tuttle Middle School, 9am to 4pm. Each week centers on one interest, such as hiking, cooking, songwriting, martial arts or STEM, with many full day field trips.', NULL, NULL, 250, 350, 350, 'week', TRUE, NULL, FALSE, TRUE, 'Withdrawing with less than two weeks notice means paying that week in full. The $50 deposit per child per week is non-refundable and non-transferable.', NULL, NULL, NULL, NULL, 2026, 'b0425b86-4eb3-552c-881a-a1c6607d6359', 'schools-out-trek-camps-south-burlington', ST_GeogFromText('SRID=4326;POINT(-73.1826 44.4365)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://docs.google.com/document/d/1-yJcmCKXQ_6rEcfxr5b1oBcKgqKvpIZIR7cN4ZmLRQU/edit?usp=sharing','https://sites.google.com/sbschools.net/schools-out/our-programs/school-age-summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE),
('CEMS Engineering & Design Summer Camps', 'University of Vermont College of Engineering and Mathematical Sciences', 'https://www.uvm.edu/cems/cems-summer-camps', NULL, 'info@cems.uvm.edu', '802-656-8413', NULL, 'Burlington', 'VT', '05405', 'Vermont', 'specialty', ARRAY['STEM']::text[], ARRAY['technology']::text[], ARRAY['CAD','3D printing','laser cutting','reverse engineering','robotics','coding','machining demos']::text[], NULL, NULL, NULL, 6, 9, 'Week long engineering camps at the University of Vermont for students entering grades 6 to 9. Campers learn computer aided design, 3D printing and robotics through hands on design challenges.', NULL, NULL, 500, 500, 500, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '87ce9c76-5e4e-5239-a884-de1d9b6e7744', 'uvm-cems-summer-camps-burlington', ST_GeogFromText('SRID=4326;POINT(-73.2121 44.4759)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.uvm.edu/cems/cems-summer-camps']::text[], '2026-11-25', '2026-11-25', TRUE)
